        if response and keep_frame_response:
            no_except_close(r.raw)
            return self.format_response(response, wb_url, full_prefix, is_timegate, is_proxy, cdx['timestamp'])
        stream = BufferedReader(r.raw, block_size=BUFF_SIZE)
