            content_type = 'text/html'
            if not self.is_framed_replay(wb_url):
                content_type += '; charset=utf-8'
            else:
                memento_ts = timegate_closest_ts or wb_url.timestamp
            response = WbResponse.text_response(response, content_type=content_type)
        if self.enable_memento and response.status_headers.statusline.startswith('200'):
            self._add_memento_links(wb_url.url, full_prefix, None, memento_ts,
                                    response.status_headers, is_timegate, is_proxy, is_memento=not is_timegate)
        return response
    def _add_memento_links(self, url, full_prefix, memento_dt, memento_ts,
                           status_headers, is_timegate, is_proxy, coll=None,
                           pref_applied=None, mod=None, is_memento=True):
        """Adds the memento link headers to supplied StatusAndHeaders instance
        :param str url: The URI-R being rewritten
        :param str full_prefix: The replay prefix
        :param str|None memento_dt: The memento datetime for the URI-R being rewritten
        :param str memento_ts: The memento timestamp
        :param warcio.StatusAndHeaders status_headers:
        :param bool is_timegate: Are we returning a response for a timegate
        :param bool is_proxy: Are we operating in proxy mode
        :param str|None coll: The collection the URI-R is from
        :param str|None pref_applied:
        :param str|None mod: The rewrite modifier
        :param bool is_memento:
        :rtype: None
        """
        replay_mod = mod or self.replay_mod
        if not memento_dt and memento_ts:
            memento_dt = timestamp_to_http_date(memento_ts)
        if memento_dt:
            if is_memento:
                status_headers.headers.append(('Memento-Datetime', memento_dt))
            if is_proxy:
                memento_url = url
            else:
                memento_url = full_prefix + memento_ts + replay_mod
                memento_url += '/' + url
        else:
            memento_url = None
        timegate_url, timemap_url = self._get_timegate_timemap(url, full_prefix, mod)
        link = []
        if not is_proxy:
            link.append(MementoUtils.make_link(url, 'original'))
            link.append(MementoUtils.make_link(timegate_url, 'timegate'))
            link.append(MementoUtils.make_link(timemap_url, 'timemap'))
        if memento_dt:
            link.append(MementoUtils.make_memento_link(memento_url, 'memento', memento_dt, coll))
        link_str = ', '.join(link)
        status_headers.headers.append(('Link', link_str))
        vary = ''
        if is_timegate:
            vary = 'accept-datetime'
        if pref_applied:
            vary = 'Prefer' if not vary else vary + ', Prefer'
            status_headers.headers.append(('Preference-Applied', pref_applied))
        if vary:
            status_headers.headers.append(('Vary', vary))
def no_except_close(closable):
    """Attempts to call the close method of the
    supplied object catching all exceptions.
    Also tries to call release_conn() in case a requests raw stream
    :param closable: The object to be closed
    :rtype: None
    """
    try:
        closable.close()
    except Exception:
        pass
    try:
        closable.release_conn()
    except Exception:
        pass
class BaseLoader(object):
    def __call__(self, cdx, params):
        entry = self.load_resource(cdx, params)
        if not entry:
            return None, None
        compress = params.get('compress') == 'gzip'
        warc_headers, other_headers, stream = entry
        source = self._get_source_id(cdx)
        out_headers = {}
        out_headers['Warcserver-Type'] = 'warc'
        out_headers['Content-Type'] = 'application/warc-record'
        if params.get('recorder_skip'):
            out_headers['Recorder-Skip'] = '1'
            cdx['recorder_skip'] = '1'
        out_headers['Warcserver-Cdx'] = to_native_str(cdx.to_cdxj().rstrip())
        out_headers['Warcserver-Source-Coll'] = to_native_str(source)
        if not warc_headers:
            if other_headers:
                out_headers['Link'] = other_headers.get('Link')
                out_headers['Memento-Datetime'] = other_headers.get('Memento-Datetime')
                if not compress:
                    known_length = other_headers.get('Content-Length')
                    if known_length:
                        out_headers['Content-Length'] = known_length
            return out_headers, StreamIter(stream, closer=call_release_conn)
        target_uri = warc_headers.get_header('WARC-Target-URI')
        out_headers['WARC-Target-URI'] = target_uri
        out_headers['Link'] = MementoUtils.make_link(target_uri, 'original')
        memento_dt = iso_date_to_datetime(warc_headers.get_header('WARC-Date'))
        out_headers['Memento-Datetime'] = datetime_to_http_date(memento_dt)
        warc_headers_buff = warc_headers.to_bytes()
        streamiter = StreamIter(stream,
                                header1=warc_headers_buff,
                                header2=other_headers,
                                closer=call_release_conn)
        if compress:
            streamiter = compress_gzip_iter(streamiter)
            out_headers['Content-Encoding'] = 'gzip'
        return out_headers, streamiter
    def raise_on_self_redirect(self, params, cdx, status_code, location_url):
        """
        Check if response is a 3xx redirect to the same url
        If so, reject this capture to avoid causing redirect loop
        """
        if cdx.get('is_live'):
            return
        if not status_code.startswith('3') or status_code == '304':
            return
        request_url = params['url'].lower()
        if not location_url:
            return
        location_url = location_url.lower()
        if location_url.startswith('/'):
            host = urlsplit(cdx['url']).netloc
            location_url = host + location_url
        location_url = location_url.split('://', 1)[-1].rstrip('/')
        request_url = request_url.split('://', 1)[-1].rstrip('/')
        self_redir = False
        orig_key = params.get('sr-urlkey') or cdx['urlkey']
        if request_url == location_url:
            self_redir = True
        elif canonicalize(location_url) == orig_key:
            self_redir = True
        if self_redir:
            msg = 'Self Redirect {0} -> {1}'
            msg = msg.format(request_url, location_url)
            params['sr-urlkey'] = orig_key
            raise LiveResourceException(msg)
class WARCPathLoader(DefaultResolverMixin, BaseLoader):
    def load_resource(self, cdx, params):
        if cdx.get('_cached_result'):
            return cdx.get('_cached_result')
        if not cdx.get('filename') or cdx.get('offset') is None:
            return None
        orig_source = cdx.get('source', '').split(':')[0]
        formatter = ParamFormatter(params, orig_source)
        cdx._formatter = formatter
        def local_index_query(local_params):
            for n, v in six.iteritems(params):
                if n.startswith('param.'):
                    local_params[n] = v
            cdx_iter, errs = self.cdx_source(local_params)
            for cdx in cdx_iter:
                cdx._formatter = formatter
                yield cdx
        failed_files = []
        headers, payload = (self.resolve_loader.
                             load_headers_and_payload(cdx,
                                                      failed_files,
                                                      local_index_query))
        http_headers_buff = None
        if payload.rec_type in ('response', 'revisit'):
            status = cdx.get('status')
            if not status or not status.startswith(('2', '4', '5')):
                http_headers = self.headers_parser.parse(payload.raw_stream)
                try:
                    orig_size = payload.raw_stream.tell()
                except:
                    orig_size = 0
                try:
                    self.raise_on_self_redirect(params, cdx,
                                                http_headers.get_statuscode(),
                                                http_headers.get_header('Location'))
                except LiveResourceException:
                    no_except_close(headers.raw_stream)
                    no_except_close(payload.raw_stream)
                    raise
                http_headers_buff = http_headers.to_bytes()
                if orig_size and len(http_headers_buff) != orig_size:
                    orig_cl = payload.rec_headers.get_header('Content-Length')
                    if orig_cl:
                        new_cl = int(orig_cl) + (len(http_headers_buff) - orig_size)
                        payload.rec_headers.replace_header('Content-Length', str(new_cl))
        warc_headers = payload.rec_headers
        if headers != payload:
            warc_headers.replace_header('WARC-Refers-To-Target-URI',
                     payload.rec_headers.get_header('WARC-Target-URI'))
            warc_headers.replace_header('WARC-Refers-To-Date',
                     payload.rec_headers.get_header('WARC-Date'))
            warc_headers.replace_header('WARC-Target-URI',
                     headers.rec_headers.get_header('WARC-Target-URI'))
            warc_headers.replace_header('WARC-Date',
                     headers.rec_headers.get_header('WARC-Date'))
            no_except_close(headers.raw_stream)
        return (warc_headers, http_headers_buff, payload.raw_stream)
class LiveWebLoader(BaseLoader):
    def load_resource(self, cdx, params):
        if cdx.get('filename') and cdx.get('offset') is not None:
            return None
        load_url = cdx.get('load_url')
        if not load_url:
            return None
        if params.get('content_type') == VideoLoader.CONTENT_TYPE:
            return None
        if self.forward_proxy_prefix and not cdx.get('is_live'):
            load_url = self.forward_proxy_prefix + load_url
        input_req = params['_input_req']
        req_headers = input_req.get_req_headers()
        dt = timestamp_to_datetime(cdx['timestamp'])
        if cdx.get('memento_url'):
            req_headers['Accept-Datetime'] = datetime_to_http_date(dt)
        method = input_req.get_req_method()
        data = input_req.get_req_body()
        p = PreparedRequest()
        try:
            p.prepare_url(load_url, None)
        except Exception:
            raise LiveResourceException(load_url)
        p.prepare_headers(None)
        p.prepare_auth(None, load_url)
        auth = p.headers.get('Authorization')
        if auth:
            req_headers['Authorization'] = auth
        load_url = p.url
        if not cdx.get('is_live'):
            req_headers['Host'] = urlsplit(p.url).netloc
            referrer = cdx.get('set_referrer')
            if referrer:
                req_headers['Referer'] = referrer
        upstream_res = self._do_request_with_redir_check(method, load_url,
                                                         data, req_headers,
                                                         params, cdx)
        memento_dt = upstream_res.headers.get('Memento-Datetime')
        if memento_dt:
            dt = http_date_to_datetime(memento_dt)
            cdx['timestamp'] = datetime_to_timestamp(dt)
        elif cdx.get('memento_url'):
            no_except_close(upstream_res)
            return None
        agg_type = upstream_res.headers.get('Warcserver-Type')
        if agg_type == 'warc':
            cdx['source'] = unquote(upstream_res.headers.get('Warcserver-Source-Coll'))
            return None, upstream_res.headers, upstream_res
        if upstream_res.version == 11:
            version = '1.1'
        else:
            version = '1.0'
        status = 'HTTP/{version} {status} {reason}\r\n'
        status = status.format(version=version,
                               status=upstream_res.status,
                               reason=upstream_res.reason)
        http_headers_buff = status
        orig_resp = upstream_res._original_response
        try:
            resp_headers = orig_resp.headers._headers
            for n, v in resp_headers:
                nl = n.lower()
                if nl in self.SKIP_HEADERS:
                    continue
                if nl in self.UNREWRITE_HEADERS:
                    v = self.unrewrite_header(cdx, v)
                http_headers_buff += n + ': ' + v + '\r\n'
            http_headers_buff += '\r\n'
            try:
                http_headers_buff = http_headers_buff.encode('utf-8')
            except:
                http_headers_buff = http_headers_buff.encode('latin-1')
        except:
            resp_headers = orig_resp.msg.headers
            for line in resp_headers:
                n, v = line.split(':', 1)
                n = n.lower()
                v = v.strip()
                if n in self.SKIP_HEADERS:
                    continue
                new_v = v
                if n in self.UNREWRITE_HEADERS:
                    new_v = self.unrewrite_header(cdx, v)
                if new_v != v:
                    http_headers_buff += n + ': ' + new_v + '\r\n'
                else:
                    http_headers_buff += line
            http_headers_buff += '\r\n'
        try:
            fp = upstream_res._fp.fp
            if hasattr(fp, 'raw'):
                fp = fp.raw
            remote_ip = fp._sock.getpeername()[0]
        except:
            remote_ip = None
        warc_headers = {}
        warc_headers['WARC-Type'] = 'response'
        warc_headers['WARC-Record-ID'] = self._make_warc_id()
        warc_headers['WARC-Target-URI'] = cdx['url']
        warc_headers['WARC-Date'] = datetime_to_iso_date(dt)
        if not cdx.get('is_live'):
            now = datetime.datetime.utcnow()
            warc_headers['WARC-Source-URI'] = cdx.get('load_url')
            warc_headers['WARC-Creation-Date'] = datetime_to_iso_date(now)
        if remote_ip:
            warc_headers['WARC-IP-Address'] = remote_ip
        ct = upstream_res.headers.get('Content-Type')
        if ct:
            metadata = self.get_custom_metadata(ct, dt)
            if metadata:
                warc_headers['WARC-JSON-Metadata'] = json.dumps(metadata)
        warc_headers['Content-Type'] = 'application/http; msgtype=response'
        if method == 'HEAD':
            content_len = 0
        else:
            content_len = upstream_res.headers.get('Content-Length', -1)
        self._set_content_len(content_len,
                              warc_headers,
                              len(http_headers_buff))
        warc_headers = StatusAndHeaders('WARC/1.0', warc_headers.items())
        return (warc_headers, http_headers_buff, upstream_res)
    def _do_request_with_redir_check(self, method, load_url,
                                     data, req_headers, params, cdx):
        upstream_res = self._do_request(method, load_url,
                                        data, req_headers, params,
                                        cdx.get('is_live'))
        if cdx.get('is_live'):
            return upstream_res
        self_redir_count = 0
        while True:
            try:
                location = upstream_res.headers.get('Location')
                self.raise_on_self_redirect(params, cdx,
                                            str(upstream_res.status),
                                            self.unrewrite_header(cdx, location))
                break
            except LiveResourceException as e:
                if load_url == location or self_redir_count >= 3:
                    raise
                load_url = location
                upstream_res = self._do_request(method, load_url, data,
                                                req_headers, params, cdx.get('is_live'))
                self_redir_count += 1
        return upstream_res
    def _do_request(self, method, load_url, data, req_headers, params, is_live):
        adapter = DefaultAdapters.live_adapter if is_live else DefaultAdapters.remote_adapter
        max_retries = adapter.max_retries
        if self.socks_proxy and not os.environ.get('SOCKS_DISABLE'):
            manager = adapter.proxy_manager_for(self.socks_proxy)
        else:
            manager = adapter.poolmanager
        upstream_res = None
        try:
            upstream_res = manager.urlopen(method=method,
                                           url=load_url,
                                           body=data,
                                           headers=req_headers,
                                           redirect=False,
                                           assert_same_host=False,
                                           preload_content=False,
                                           decode_content=False,
                                           retries=max_retries,
                                           timeout=params.get('_timeout'))
            return upstream_res
        except Exception as e:
            if upstream_res:
                no_except_close(upstream_res)
            if logger.isEnabledFor(logging.DEBUG):
                import traceback
                traceback.print_exc()
                logger.debug('FAILED: ' + method + ' ' + load_url + ': ' + str(e))
            raise LiveResourceException(load_url)
class RecorderApp(object):
    def _put_record(self, request_uri, input_buff, record_type,
                    headers, params, start_response):
        if record_type == 'stream':
            if self.writer.write_stream_to_file(params, input_buff):
                msg = {'success': 'true'}
            else:
                msg = {'error_message': 'upload_error'}
            return self.send_message(msg, '200 OK',
                                     start_response)
        req_stream = None
        try:
            req_stream = ReqWrapper(input_buff,
                                    headers,
                                    params,
                                    self.create_buff_func)
            while True:
                buff = req_stream.read()
                if not buff:
                    break
            content_type = headers.get('Content-Type')
            payload_length = req_stream.out.tell()
            req_stream.out.seek(0)
            record = self.writer.create_warc_record(uri=params['url'],
                                                    record_type=record_type,
                                                    payload=req_stream.out,
                                                    length=payload_length,
                                                    warc_content_type=content_type,
                                                    warc_headers_dict=req_stream.headers)
            self.writer.write_record(record, params)
            msg = {'success': 'true',
                   'WARC-Date': record.rec_headers.get_header('WARC-Date')}
        finally:
            if req_stream:
                no_except_close(req_stream.out)
        return self.send_message(msg,
                                 '200 OK',
                                 start_response)
    def handle_call(self, environ, start_response):
        input_req = DirectWSGIInputRequest(environ)
        params = self._get_params(environ)
        request_uri = input_req.get_full_request_uri()
        input_buff = input_req.get_req_body()
        headers = input_req.get_req_headers()
        method = input_req.get_req_method()
        path = environ['PATH_INFO']
        put_record = params.get('put_record')
        if put_record and method in ('PUT', 'POST'):
            return self._put_record(request_uri,
                                    input_buff,
                                    put_record,
                                    headers,
                                    params,
                                    start_response)
        skipping = any(x.skip_request(path, headers) for x in self.skip_filters)
        req_is_wrapped = False
        if not skipping:
            req_stream = ReqWrapper(input_buff,
                                    headers,
                                    params,
                                    self.create_buff_func)
            req_is_wrapped = True
        else:
            req_stream = input_buff
        data = None
        if input_buff:
            data = req_stream
        try:
            res = requests.request(url=self.upstream_host + request_uri,
                                   method=method,
                                   data=data,
                                   headers=headers,
                                   allow_redirects=False,
                                   stream=True)
            res.raise_for_status()
        except Exception as e:
            if req_is_wrapped:
                no_except_close(req_stream.out)
            return self.send_error(e, start_response)
        if not skipping:
            skipping = any(x.skip_response(path,
                                           req_stream.headers,
                                           res.headers,
                                           params)
                           for x in self.skip_filters)
        if not skipping:
            resp_stream = RespWrapper(res.raw,
                                      res.headers,
                                      req_stream,
                                      params,
                                      self.write_queue,
                                      path,
                                      self.create_buff_func)
        else:
            resp_stream = res.raw
            if req_is_wrapped:
                no_except_close(req_stream.out)
        resp_iter = StreamIter(resp_stream)
        res.headers.pop('Transfer-Encoding', '')
        start_response('200 OK', list(res.headers.items()))
        return resp_iter
class ResolvingLoader(object):
    def __call__(self, cdx, failed_files, cdx_loader, *args, **kwargs):
        headers_record, payload_record = self.load_headers_and_payload(cdx, failed_files, cdx_loader)
        if not headers_record:
            headers_record = payload_record
        elif headers_record != payload_record:
            no_except_close(headers_record.raw_stream)
            if not headers_record.http_headers.headers:
                headers_record = payload_record
        if not headers_record or not payload_record:
            if headers_record:
                no_except_close(headers_record.raw_stream)
            if payload_record:
                no_except_close(payload_record.raw_stream)
            raise ArchiveLoadFailed('Could not load ' + str(cdx))
        headers_record.http_headers.validate_statusline('204 No Content')
        return (headers_record.http_headers, payload_record.raw_stream)
class ZipNumIndexSource(BaseIndexSource):
    def compute_page_range(self, reader, query):
        pagesize = query.page_size
        if not pagesize:
            pagesize = self.max_blocks
        else:
            try:
                pagesize = int(pagesize)
            except ValueError:
                msg = 'Invalid value for pageSize= param: {}'
                raise CDXException(msg.format(pagesize))
        last_line = None
        end_iter = search(reader, query.end_key, prev_size=1)
        try:
            end_line = six.next(end_iter)
        except StopIteration:
            last_line = read_last_line(reader)
            end_line = last_line
        first_iter = iter_range(reader,
                                query.key,
                                query.end_key,
                                prev_size=1)
        try:
            first_line = six.next(first_iter)
        except StopIteration:
            if end_line == last_line and query.key >= last_line:
                first_line = last_line
            else:
                no_except_close(reader)
                if query.page_count:
                    yield self._page_info(0, pagesize, 0)
                return
        first = IDXObject(first_line)
        end = IDXObject(end_line)
        try:
            blocks = end['lineno'] - first['lineno']
            total_pages = int(blocks / pagesize) + 1
        except:
            blocks = -1
            total_pages = 1
        if query.page_count:
            if blocks == 0:
                try:
                    block_cdx_iter = self.idx_to_cdx([first_line], query)
                    block = six.next(block_cdx_iter)
                    cdx = six.next(block)
                except StopIteration:
                    total_pages = 0
                    blocks = -1
            yield self._page_info(total_pages, pagesize, blocks + 1)
            no_except_close(reader)
            return
        curr_page = query.page
        if curr_page >= total_pages or curr_page < 0:
            msg = 'Page {0} invalid: First Page is 0, Last Page is {1}'
            no_except_close(reader)
            raise CDXException(msg.format(curr_page, total_pages - 1))
        startline = curr_page * pagesize
        endline = startline + pagesize - 1
        if blocks >= 0:
            endline = min(endline, blocks)
        if curr_page == 0:
            yield first_line
        else:
            startline -= 1
        try:
            idxiter = itertools.islice(first_iter, startline, endline)
            for idx in idxiter:
                yield idx
        except Exception:
            pass
        finally:
            no_except_close(reader)

