class DynamicGroup(OrganizationalModel):
    def _set_object_classes(self, model):
        """
        Given the `content_type` for this group, dynamically map object classes to this instance.
        Protocol for return values:
        - True: Model and object classes mapped.
        - False: Model not yet mapped (likely because of no `content_type`)
        """
        if getattr(self, "_object_classes_mapped", False):
            return True
        try:
            self.filterset_class = get_filterset_for_model(model)
            self.filterform_class = get_form_for_model(model, form_prefix="Filter")
            self.form_class = get_form_for_model(model)
        except TypeError:
            logger.debug("Failed to map object classes for model %s", model)
            self.filterset_class = None
            self.filterform_class = None
            self.form_class = None
            self._object_classes_mapped = False
        else:
            self._object_classes_mapped = True
        return self._object_classes_mapped
    @property
    def members_cached(self):
        """Return the member objects for this group, cached if available."""
        unpickled_query = None
        try:
            cached_query = cache.get(self.members_cache_key)
            if cached_query is not None:
                unpickled_query = pickle.loads(cached_query)
        except pickle.UnpicklingError:
            logger.warning("Failed to unpickle cached members for %s", self)
        finally:
            if unpickled_query is None:
                unpickled_query = self.members.all()
                cached_query = pickle.dumps(unpickled_query)
                cache.set(
                    self.members_cache_key, cached_query, get_settings_or_config("DYNAMIC_GROUPS_MEMBER_CACHE_TIMEOUT")
                )
        return unpickled_query
@receiver(post_save)
@receiver(m2m_changed)
def _handle_changed_object(sender, instance, raw=False, **kwargs):
    """
    Fires when an object is created or updated.
    """
    from .jobs import enqueue_job_hooks
    if raw:
        return
    if change_context_state.get() is None:
        return
    object_m2m_changed = False
    if kwargs.get("created"):
        action = ObjectChangeActionChoices.ACTION_CREATE
    elif "created" in kwargs:
        action = ObjectChangeActionChoices.ACTION_UPDATE
    elif kwargs.get("action") in ["post_add", "post_remove"] and kwargs["pk_set"]:
        object_m2m_changed = True
        action = ObjectChangeActionChoices.ACTION_UPDATE
    else:
        return
    if hasattr(instance, "to_objectchange"):
        original_cache = instance._state.fields_cache.copy()
        if object_m2m_changed:
            related_changes = ObjectChange.objects.filter(
                changed_object_type=ContentType.objects.get_for_model(instance),
                changed_object_id=instance.pk,
                request_id=change_context_state.get().change_id,
            )
            m2m_changes = instance.to_objectchange(action)
            related_changes.update(object_data=m2m_changes.object_data, object_data_v2=m2m_changes.object_data_v2)
            objectchange = related_changes.first() if related_changes.exists() else None
        else:
            objectchange = instance.to_objectchange(action)
            objectchange.user = _get_user_if_authenticated(change_context_state.get().get_user(), objectchange)
            objectchange.request_id = change_context_state.get().change_id
            objectchange.change_context = change_context_state.get().context
            objectchange.change_context_detail = change_context_state.get().context_detail[
                :CHANGELOG_MAX_CHANGE_CONTEXT_DETAIL
            ]
            objectchange.save()
        instance._state.fields_cache = original_cache
        if objectchange is not None:
            enqueue_job_hooks(objectchange)
    enqueue_webhooks(instance, change_context_state.get().get_user(), change_context_state.get().change_id, action)
    if action == ObjectChangeActionChoices.ACTION_CREATE:
        model_inserts.labels(instance._meta.model_name).inc()
    elif action == ObjectChangeActionChoices.ACTION_UPDATE:
        model_updates.labels(instance._meta.model_name).inc()
    changelog_retention = get_settings_or_config("CHANGELOG_RETENTION")
    if changelog_retention and random.randint(1, 1000) == 1:
        cutoff = timezone.now() - timedelta(days=changelog_retention)
        ObjectChange.objects.filter(time__lt=cutoff).delete()
