    name = value.split("|")[0]
    try:
        remember_key = userManager.signature_key_for_user(
            name, salt=current_app.config["SECRET_KEY"]
        )
        timestamp = datetime.utcnow().timestamp()
        return encode_cookie(f"{name}|{timestamp}", key=remember_key)
    except Exception:
        pass
