            errorCode = STATUS_SMB_BAD_TID
        if errorCode > 0:
            respParameters = b''
            respData       = b''
        respSMBCommand['Parameters']             = respParameters
        respSMBCommand['Data']                   = respData
        smbServer.setConnectionData(connId, connData)
