        argument_defaults = []
        for arg in function.args:
            argname = fix_bad_arg_names(function, arg)
            default = get_arg_default(arg)
            if argname == 'vararg':
                for j in range(5):
                    argname = 'vararg_%i' % j
                    argument_names.append(argname)
