        raise TypeMismatch(f"Cannot cast from {src.typ} to {dst.typ}")
    if src.value == "~empty" and src.typ.maxlen != dst.typ.maxlen:
        raise TypeMismatch(
            f"Bad type for clearing bytes: expected {dst.typ} but got {src.typ}"
