        if isinstance(typ, TupleLike):
            ret = _get_element_ptr_tuplelike(parent, key)
        elif isinstance(typ, MappingType):
            ret = _get_element_ptr_mapping(parent, key)
        elif isinstance(typ, ArrayLike):
