                response['Content-Length'] = 0
            return []
        if isinstance(out, (tuple, list))\
        and isinstance(out[0], (bytes, unicode)):
            out = out[0][0:0].join(out)
        if isinstance(out, unicode):
            out = out.encode(response.charset)
