        assert is_symbol(sym) or is_mem_sym(sym)
        if isinstance(ofst.value, int):
            return ["_OFST", sym, ofst.value]
        else:
            ofst = _compile_to_assembly(ofst, withargs, existing_labels, break_dest, height_)
            return ofst + [sym, "ADD"]
