def init(config):
    global DATAROOT
    DATAROOT = config.dataroot
    global DB_HOST, DB_DBNAME, DB_USER, DB_PASSWORD, DB_PORT
    DB_HOST = config.yfcc100m_db_host
    DB_DBNAME = config.yfcc100m_db_dbname
