            warnings.warn(
                "In future versions of Waitress clear_untrusted_proxy_headers will be "
                "set to True by default. You may opt-out by setting this value to "
                "False, or opt-in explicitly by setting this to True.",
                DeprecationWarning,
            )
            self.clear_untrusted_proxy_headers = False
        self.listen = wanted_sockets
        self.check_sockets(self.sockets)
class BaseWSGIServer(wasyncore.dispatcher, object):
    def __init__(
        self,
        application,
        map=None,
        _start=True,
        _sock=None,
        dispatcher=None,
        adj=None,
        sockinfo=None,
        bind_socket=True,
        **kw
    ):
        if adj is None:
            adj = Adjustments(**kw)
        if adj.trusted_proxy or adj.clear_untrusted_proxy_headers:
            application = proxy_headers_middleware(
                application,
                trusted_proxy=adj.trusted_proxy,
                trusted_proxy_count=adj.trusted_proxy_count,
                trusted_proxy_headers=adj.trusted_proxy_headers,
                clear_untrusted=adj.clear_untrusted_proxy_headers,
                log_untrusted=adj.log_untrusted_proxy_headers,
                logger=self.logger,
            )
        if map is None:
            map = {}
        if sockinfo is None:
            sockinfo = adj.listen[0]
        self.sockinfo = sockinfo
        self.family = sockinfo[0]
        self.socktype = sockinfo[1]
        self.application = application
        self.adj = adj
        self.trigger = trigger.trigger(map)
        if dispatcher is None:
            dispatcher = ThreadedTaskDispatcher()
            dispatcher.set_thread_count(self.adj.threads)
        self.task_dispatcher = dispatcher
        self.asyncore.dispatcher.__init__(self, _sock, map=map)
        if _sock is None:
            self.create_socket(self.family, self.socktype)
            if self.family == socket.AF_INET6:
                self.socket.setsockopt(IPPROTO_IPV6, IPV6_V6ONLY, 1)
        self.set_reuse_addr()
        if bind_socket:
            self.bind_server_socket()
        self.effective_host, self.effective_port = self.getsockname()
        self.server_name = self.get_server_name(self.effective_host)
        self.active_channels = {}
        if _start:
            self.accept_connections()
def find_double_newline(s):
    """Returns the position just after a double newline in the given string."""
    pos = s.find(b"\r\n\r\n")
    if pos >= 0:
        pos += 4
    return pos
def undquote(value):
    if value.startswith('"') and value.endswith('"'):
        matches = quoted_string.match(value)
        if matches and matches.end() == len(value):
            value = value[1:-1]
            value = quoted_pair.sub(r"\1", value)
            return value
    elif not value.startswith('"') and not value.endswith('"'):
        return value
    raise ValueError("Invalid quoting in value")

POST_LOGIN_ROUTES = (
    "hc-checks",
    "hc-details",
    "hc-log",
    "hc-channels",
    "hc-add-slack",
    "hc-add-pushover",
    "hc-add-telegram",
    "hc-project-settings",
    "hc-uncloak",
)
def _allow_redirect(redirect_url):
    if not redirect_url:
        return False
    parsed = urlparse(redirect_url)
    if parsed.netloc:
        return False
    try:
        match = resolve(parsed.path)
    except Resolver404:
        return False
    return match.url_name in POST_LOGIN_ROUTES
def _make_user(email, tz=None, with_project=True):
    username = str(uuid.uuid4())[:30]
    user = User(username=username, email=email)
    user.set_unusable_password()
    user.save()
    project = None
    if with_project:
        project = Project(owner=user)
        project.badge_key = user.username
        project.save()
        check = Check(project=project)
        check.set_name_slug("My First Check")
        check.save()
        channel = Channel(project=project)
        channel.kind = "email"
        channel.value = email
        channel.email_verified = True
        channel.save()
        channel.checks.add(check)
    profile = Profile.objects.for_user(user)
    if tz:
        profile.tz = tz
        profile.save()
    return user
def _redirect_after_login(request):
    """Redirect to the URL indicated in ?next= query parameter."""
    redirect_url = request.GET.get("next")
    if _allow_redirect(redirect_url):
        return redirect(redirect_url)
    if request.user.project_set.count() == 1:
        project = request.user.project_set.first()
        return redirect("hc-checks", project.code)
    return redirect("hc-index")
def _check_2fa(request, user):
    have_keys = user.credentials.exists()
    profile = Profile.objects.for_user(user)
    if have_keys or profile.totp:
        request.session["2fa_user"] = [user.id, user.email, int(time.time())]
        if have_keys:
            path = reverse("hc-login-webauthn")
        else:
            path = reverse("hc-login-totp")
        redirect_url = request.GET.get("next")
        if _allow_redirect(redirect_url):
            path += "?next=%s" % redirect_url
        return redirect(path)
    auth_login(request, user)
    return _redirect_after_login(request)
def login(request):
    form = forms.PasswordLoginForm()
    magic_form = forms.EmailLoginForm()
    if request.method == "POST":
        if request.POST.get("action") == "login":
            form = forms.PasswordLoginForm(request.POST)
            if form.is_valid():
                return _check_2fa(request, form.user)
        else:
            magic_form = forms.EmailLoginForm(request.POST)
            if magic_form.is_valid():
                redirect_url = request.GET.get("next")
                if not _allow_redirect(redirect_url):
                    redirect_url = None
                profile = Profile.objects.for_user(magic_form.user)
                profile.send_instant_login_link(redirect_url=redirect_url)
                response = redirect("hc-login-link-sent")
                response.set_cookie("auto-login", "1", max_age=300, httponly=True)
                return response
    if request.user.is_authenticated:
        return _redirect_after_login(request)
    bad_link = request.session.pop("bad_link", None)
    ctx = {
        "page": "login",
        "form": form,
        "magic_form": magic_form,
        "bad_link": bad_link,
        "registration_open": settings.REGISTRATION_OPEN,
        "support_email": settings.SUPPORT_EMAIL,
    }
    return render(request, "accounts/login.html", ctx)
@require_POST
@csrf_exempt
def signup(request):
    if not settings.REGISTRATION_OPEN:
        return HttpResponseForbidden()
    ctx = {}
    form = forms.SignupForm(request.POST)
    if form.is_valid():
        email = form.cleaned_data["identity"]
        tz = form.cleaned_data["tz"]
        user = _make_user(email, tz)
        profile = Profile.objects.for_user(user)
        profile.send_instant_login_link()
        ctx["created"] = True
    else:
        ctx = {"form": form}
    response = render(request, "accounts/signup_result.html", ctx)
    if ctx.get("created"):
        response.set_cookie("auto-login", "1", max_age=300, httponly=True)
    return response
def check_token(request, username, token, new_email=None):
    if request.user.is_authenticated:
        auth_logout(request)
    if request.method != "POST" and "auto-login" not in request.COOKIES:
        return render(request, "accounts/check_token_submit.html")
    user = authenticate(username=username, token=token)
    if user is not None and user.is_active:
        if new_email:
            if User.objects.filter(email=new_email).exists():
                request.session["bad_link"] = True
                return redirect("hc-login")
            user.email = new_email
            user.set_unusable_password()
            user.save()
        user.profile.token = ""
        user.profile.save()
        return _check_2fa(request, user)
