class Expr:
    def parse_Attribute(self):
        typ = self.expr._metadata["type"]
        if (
            isinstance(typ, EnumT)
            and isinstance(self.expr.value, vy_ast.Name)
            and typ.name == self.expr.value.id
        ):
            enum_id = typ._enum_members[self.expr.attr]
            value = 2**enum_id
            return IRnode.from_list(value, typ=typ)
        if self.expr.attr == "balance":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if addr.typ == AddressT():
                if (
                    isinstance(self.expr.value, vy_ast.Name)
                    and self.expr.value.id == "self"
                    and version_check(begin="istanbul")
                ):
                    seq = ["selfbalance"]
                else:
                    seq = ["balance", addr]
                return IRnode.from_list(seq, typ=UINT256_T)
        elif self.expr.attr == "codesize" or self.expr.attr == "is_contract":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if addr.typ == AddressT():
                if self.expr.attr == "codesize":
                    if self.expr.get("value.id") == "self":
                        eval_code = ["codesize"]
                    else:
                        eval_code = ["extcodesize", addr]
                    output_type = UINT256_T
                else:
                    eval_code = ["gt", ["extcodesize", addr], 0]
                    output_type = BoolT()
                return IRnode.from_list(eval_code, typ=output_type)
        elif self.expr.attr == "codehash":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if not version_check(begin="constantinople"):
                raise EvmVersionException(
                    "address.codehash is unavailable prior to constantinople ruleset", self.expr
                )
            if addr.typ == AddressT():
                return IRnode.from_list(["extcodehash", addr], typ=BYTES32_T)
        elif self.expr.attr == "code":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if addr.typ == AddressT():
                if addr.value == "address":
                    return IRnode.from_list(["~selfcode"], typ=BytesT(0))
                return IRnode.from_list(["~extcode", addr], typ=BytesT(0))
        elif isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id == "self":
            varinfo = self.context.globals[self.expr.attr]
            return IRnode.from_list(
                varinfo.position.position,
                typ=varinfo.typ,
                location=STORAGE,
                annotation="self." + self.expr.attr,
            )
        elif (
            isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id in ENVIRONMENT_VARIABLES
        ):
            key = f"{self.expr.value.id}.{self.expr.attr}"
            if key == "msg.sender":
                return IRnode.from_list(["caller"], typ=AddressT())
            elif key == "msg.data":
                return IRnode.from_list(["~calldata"], typ=BytesT(0))
            elif key == "msg.value" and self.context.is_payable:
                return IRnode.from_list(["callvalue"], typ=UINT256_T)
            elif key == "msg.gas":
                return IRnode.from_list(["gas"], typ=UINT256_T)
            elif key == "block.prevrandao":
                if not version_check(begin="paris"):
                    warning = VyperException(
                        "tried to use block.prevrandao in pre-Paris "
                        "environment! Suggest using block.difficulty instead.",
                        self.expr,
                    )
                    vyper_warn(str(warning))
                return IRnode.from_list(["prevrandao"], typ=UINT256_T)
            elif key == "block.difficulty":
                if version_check(begin="paris"):
                    warning = VyperException(
                        "tried to use block.difficulty in post-Paris "
                        "environment! Suggest using block.prevrandao instead.",
                        self.expr,
                    )
                    vyper_warn(str(warning))
                return IRnode.from_list(["difficulty"], typ=UINT256_T)
            elif key == "block.timestamp":
                return IRnode.from_list(["timestamp"], typ=UINT256_T)
            elif key == "block.coinbase":
                return IRnode.from_list(["coinbase"], typ=AddressT())
            elif key == "block.number":
                return IRnode.from_list(["number"], typ=UINT256_T)
            elif key == "block.gaslimit":
                return IRnode.from_list(["gaslimit"], typ=UINT256_T)
            elif key == "block.basefee":
                return IRnode.from_list(["basefee"], typ=UINT256_T)
            elif key == "block.prevhash":
                return IRnode.from_list(["blockhash", ["sub", "number", 1]], typ=BYTES32_T)
            elif key == "tx.origin":
                return IRnode.from_list(["origin"], typ=AddressT())
            elif key == "tx.gasprice":
                return IRnode.from_list(["gasprice"], typ=UINT256_T)
            elif key == "chain.id":
                if not version_check(begin="istanbul"):
                    raise EvmVersionException(
                        "chain.id is unavailable prior to istanbul ruleset", self.expr
                    )
                return IRnode.from_list(["chainid"], typ=UINT256_T)
        else:
            sub = Expr(self.expr.value, self.context).ir_node
            if isinstance(sub.typ, InterfaceT):
                assert self.expr.attr == "address"
                sub.typ = typ
                return sub
            if isinstance(sub.typ, StructT) and self.expr.attr in sub.typ.member_types:
                return get_element_ptr(sub, self.expr.attr)
    def build_in_comparator(self):
        left = Expr(self.expr.left, self.context).ir_node
        right = Expr(self.expr.right, self.context).ir_node
        if not left.typ._is_prim_word:
            raise TypeMismatch(
                "`in` not allowed for arrays of non-base types, tracked in issue
            )
        left = unwrap_location(left)
        if isinstance(self.expr.op, vy_ast.In):
            found, not_found = 1, 0
        elif isinstance(self.expr.op, vy_ast.NotIn):
            found, not_found = 0, 1
        else:
            return
        i = IRnode.from_list(self.context.fresh_varname("in_ix"), typ=UINT256_T)
        found_ptr = self.context.new_internal_variable(BoolT())
        ret = ["seq"]
        with left.cache_when_complex("needle") as (b1, left), right.cache_when_complex(
            "haystack"
        ) as (b2, right):
            if right.value == "multi":
                assert len(right.args) > 0
                args = [unwrap_location(val) for val in right.args]
                if isinstance(self.expr.op, vy_ast.In):
                    checks = [["eq", left, val] for val in args]
                    return b1.resolve(b2.resolve(Expr._logical_or(checks)))
                if isinstance(self.expr.op, vy_ast.NotIn):
                    checks = [["ne", left, val] for val in args]
                    return b1.resolve(b2.resolve(Expr._logical_and(checks)))
                return
            ith_element_ptr = get_element_ptr(right, i, array_bounds_check=False)
            ith_element = unwrap_location(ith_element_ptr)
            if isinstance(right.typ, SArrayT):
                len_ = right.typ.count
            else:
                len_ = get_dyn_array_count(right)
            loop_body = [
                "if",
                ["eq", left, ith_element],
                ["seq", ["mstore", found_ptr, found], "break"],
            ]
            loop = ["repeat", i, 0, len_, right.typ.count, loop_body]
            ret.append(["seq", ["mstore", found_ptr, not_found], loop, ["mload", found_ptr]])
            return IRnode.from_list(b1.resolve(b2.resolve(ret)), typ=BoolT())
class IRnode:
    def __init__(
        self,
        value: Union[str, int],
        args: List["IRnode"] = None,
        typ: VyperType = None,
        location: Optional[AddrSpace] = None,
        source_pos: Optional[Tuple[int, int]] = None,
        annotation: Optional[str] = None,
        error_msg: Optional[str] = None,
        mutable: bool = True,
        add_gas_estimate: int = 0,
        encoding: Encoding = Encoding.VYPER,
    ):
        if args is None:
            args = []
        self.value = value
        self.args = args
        assert isinstance(typ, VyperType) or typ is None, repr(typ)
        self.typ = typ
        self.location = location
        self.source_pos = source_pos
        self.error_msg = error_msg
        self.annotation = annotation
        self.mutable = mutable
        self.add_gas_estimate = add_gas_estimate
        self.encoding = encoding
        self.as_hex = AS_HEX_DEFAULT
        def _check(condition, err):
            if not condition:
                raise CompilerPanic(str(err))
        _check(self.value is not None, "None is not allowed as IRnode value")
        if isinstance(self.value, int):
            _check(len(self.args) == 0, "int can't have arguments")
            _check(-(2**255) <= self.value < 2**256, "out of range")
            self.valency = 1
            self._gas = 5
        elif isinstance(self.value, str):
            if self.value.upper() in get_ir_opcodes():
                _, ins, outs, gas = get_ir_opcodes()[self.value.upper()]
                self.valency = outs
                _check(
                    len(self.args) == ins,
                    f"Number of arguments mismatched: {self.value} {self.args}",
                )
                self._gas = gas + 2 * (outs - ins)
                for arg in self.args:
                    zero_valency_whitelist = {"pass", "pop"}
                    _check(
                        arg.valency == 1 or arg.value in zero_valency_whitelist,
                        f"invalid argument to `{self.value}`: {arg}",
                    )
                    self._gas += arg.gas
                if self.value.upper()[0:3] == "LOG" and isinstance(self.args[1].value, int):
                    self._gas += self.args[1].value * 8
                if self.value.upper() == "CALL" and self.args[2].value != 0:
                    self._gas += 34000
                elif self.value.upper() == "SSTORE" and self.args[1].value != 0:
                    self._gas += 15000
                elif self.value.upper() in ("CALLDATACOPY", "CODECOPY", "EXTCODECOPY"):
                    size = 34000
                    size_arg_index = 3 if self.value.upper() == "EXTCODECOPY" else 2
                    size_arg = self.args[size_arg_index]
                    if isinstance(size_arg.value, int):
                        size = size_arg.value
                    self._gas += ceil32(size) // 32 * 3
                if self.value.upper() == "CALL" and isinstance(self.args[0].value, int):
                    self._gas += self.args[0].value
            elif self.value == "if":
                if len(self.args) == 3:
                    self._gas = self.args[0].gas + max(self.args[1].gas, self.args[2].gas) + 3
                if len(self.args) == 2:
                    self._gas = self.args[0].gas + self.args[1].gas + 17
                _check(
                    self.args[0].valency > 0,
                    f"zerovalent argument as a test to an if statement: {self.args[0]}",
                )
                _check(len(self.args) in (2, 3), "if statement can only have 2 or 3 arguments")
                self.valency = self.args[1].valency
            elif self.value == "with":
                _check(len(self.args) == 3, self)
                _check(
                    len(self.args[0].args) == 0 and isinstance(self.args[0].value, str),
                    f"first argument to with statement must be a variable name: {self.args[0]}",
                )
                _check(
                    self.args[1].valency == 1 or self.args[1].value == "pass",
                    f"zerovalent argument to with statement: {self.args[1]}",
                )
                self.valency = self.args[2].valency
                self._gas = sum([arg.gas for arg in self.args]) + 5
            elif self.value == "repeat":
                _check(
                    len(self.args) == 5, "repeat(index_name, startval, rounds, rounds_bound, body)"
                )
                counter_ptr = self.args[0]
                start = self.args[1]
                repeat_count = self.args[2]
                repeat_bound = self.args[3]
                body = self.args[4]
                _check(
                    isinstance(repeat_bound.value, int) and repeat_bound.value > 0,
                    f"repeat bound must be a compile-time positive integer: {self.args[2]}",
                )
                _check(repeat_count.valency == 1, repeat_count)
                _check(counter_ptr.valency == 1, counter_ptr)
                _check(start.valency == 1, start)
                self.valency = 0
                self._gas = counter_ptr.gas + start.gas
                self._gas += 3
                int_bound = int(repeat_bound.value)
                self._gas += int_bound * (body.gas + 50) + 30
                if repeat_count != repeat_bound:
                    self._gas += 18
            elif self.value == "seq":
                self.valency = self.args[-1].valency if self.args else 0
                self._gas = sum([arg.gas for arg in self.args]) + 30
            elif self.value in ("goto", "exit_to"):
                for arg in self.args:
                    _check(
                        arg.valency == 1 or arg.value == "pass",
                        f"zerovalent argument to goto {arg}",
                    )
                self.valency = 0
                self._gas = sum([arg.gas for arg in self.args])
            elif self.value == "label":
                if not self.args[1].value == "var_list":
                    raise CodegenPanic(f"2nd argument to label must be var_list, {self}")
                self.valency = 0
                self._gas = 1 + sum(t.gas for t in self.args)
            elif self.value == "unique_symbol":
                self.valency = 0
                self._gas = 0
            elif self.value == "var_list":
                for arg in self.args:
                    if not isinstance(arg.value, str) or len(arg.args) > 0:
                        raise CodegenPanic(f"var_list only takes strings: {self.args}")
                self.valency = 0
                self._gas = 0
            elif self.value == "multi":
                for arg in self.args:
                    _check(
                        arg.valency > 0, f"Multi expects all children to not be zerovalent: {arg}"
                    )
                self.valency = sum([arg.valency for arg in self.args])
                self._gas = sum([arg.gas for arg in self.args])
            elif self.value == "deploy":
                self.valency = 0
                _check(len(self.args) == 3, f"`deploy` should have three args {self}")
                self._gas = NullAttractor()
            else:
                self.valency = 1
                self._gas = 3
        elif self.value is None:
            self.valency = 1
            self._gas = 3
        else:
            raise CompilerPanic(f"Invalid value for IR AST node: {self.value}")
        assert isinstance(self.args, list)
def _optimize_binop(binop, args, ann, parent_op):
    fn, symb, unsigned = arith[binop]
    def _int(x, unsigned=unsigned):
        return _evm_int(x, unsigned=unsigned)
    def _wrap(x):
        return _wrap256(x, unsigned=unsigned)
    new_ann = None
    if ann is not None:
        l_ann = _shorten_annotation(args[0].annotation or str(args[0]))
        r_ann = _shorten_annotation(args[1].annotation or str(args[1]))
        new_ann = l_ann + symb + r_ann
        new_ann = f"{ann} ({new_ann})"
    def finalize(new_val, new_args):
        rollback = (args[0].is_complex_ir and not _deep_contains(new_args, args[0])) or (
            args[1].is_complex_ir and not _deep_contains(new_args, args[1])
        )
        if rollback:
            return None
        return new_val, new_args, new_ann
    if _is_int(args[0]) and _is_int(args[1]):
        left, right = _int(args[0]), _int(args[1])
        new_val = fn(left, right)
        new_val = _wrap(new_val)
        return finalize(new_val, [])
    is_truthy = parent_op in {"if", "assert", "iszero"}
    def _conservative_eq(x, y):
        return x.args == y.args == [] and x.value == y.value and not x.is_complex_ir
    if binop in COMMUTATIVE_OPS and _is_int(args[0]):
        args = [args[1], args[0]]
    if binop in {"add", "sub", "xor", "or"} and _int(args[1]) == 0:
        return finalize("seq", [args[0]])
    if binop in {"sub", "xor", "ne"} and _conservative_eq(args[0], args[1]):
        return finalize(0, [])
    if binop == "eq" and _conservative_eq(args[0], args[1]):
        return finalize(1, [])
    if binop in {"mul", "div", "sdiv", "mod", "smod", "and"} and _int(args[1]) == 0:
        return finalize(0, [])
    if binop in {"mod", "smod"} and _int(args[1]) == 1:
        return finalize(0, [])
    if binop in {"mul", "div", "sdiv"} and _int(args[1]) == 1:
        return finalize("seq", [args[0]])
    if binop in {"mul", "sdiv"} and _int(args[1], SIGNED) == -1:
        return finalize("sub", [0, args[0]])
    if binop in {"and", "or", "xor"} and _int(args[1], SIGNED) == -1:
        assert unsigned == UNSIGNED
        if binop == "and":
            return finalize("seq", [args[0]])
        if binop == "xor":
            return finalize("not", [args[0]])
        if binop == "or":
            return finalize(args[1].value, [])
        raise CompilerPanic("unreachable")
    if binop == "sub" and _int(args[0], SIGNED) == -1:
        return finalize("not", [args[1]])
    if binop == "exp":
        if _int(args[1]) == 0 or _int(args[0]) == 1:
            return finalize(1, [])
        if _int(args[0]) == 0:
            return finalize("iszero", [args[1]])
        if _int(args[1]) == 1:
            return finalize("seq", [args[0]])
    if binop in {"mod", "div", "mul"} and _is_int(args[1]) and is_power_of_two(_int(args[1])):
        assert unsigned == UNSIGNED, "something's not right."
        if binop == "mod":
            return finalize("and", [args[0], _int(args[1]) - 1])
        if binop == "div" and version_check(begin="constantinople"):
            return finalize("shr", [int_log2(_int(args[1])), args[0]])
        if binop == "mul" and version_check(begin="constantinople"):
            return finalize("shl", [int_log2(_int(args[1])), args[0]])
        if version_check(begin="constantinople"):
            raise CompilerPanic("unreachable")
    if binop == "eq" and _int(args[1]) == 0:
        return finalize("iszero", [args[0]])
    if binop == "ne" and _int(args[1]) == 0:
        return finalize("iszero", [["iszero", args[0]]])
    if binop == "eq" and _int(args[1], SIGNED) == -1:
        return finalize("iszero", [["not", args[0]]])
    if is_truthy:
        if binop == "eq":
            assert unsigned == UNSIGNED
            return finalize("iszero", [["xor", args[0], args[1]]])
        if binop == "ne" and parent_op == "iszero":
            return finalize("iszero", [["eq", *args]])
        if binop == "or" and _is_int(args[1]) and _int(args[1]) != 0:
            return finalize(1, [])
    if binop in COMPARISON_OPS:
        prefer_strict = not is_truthy
        res = _comparison_helper(binop, args, prefer_strict=prefer_strict)
        if res is None:
            return res
        new_op, new_args = res
        return finalize(new_op, new_args)
    return None
def _unpack_returndata(buf, fn_type, call_kwargs, contract_address, context, expr):
    return_t = fn_type.return_type
    if return_t is None:
        return ["pass"], 0, 0
    wrapped_return_t = calculate_type_for_external_return(return_t)
    abi_return_t = wrapped_return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    encoding = Encoding.ABI
    buf = IRnode.from_list(
        buf,
        typ=wrapped_return_t,
        location=MEMORY,
        encoding=encoding,
        annotation=f"{expr.node_source_code} returndata buffer",
    )
    unpacker = ["seq"]
    if not call_kwargs.skip_contract_check:
        assertion = IRnode.from_list(
            ["assert", ["ge", "returndatasize", min_return_size]],
            error_msg="returndatasize too small",
        )
        unpacker.append(assertion)
    assert isinstance(wrapped_return_t, TupleT)
    if needs_clamp(wrapped_return_t, encoding):
        return_buf = context.new_internal_variable(wrapped_return_t)
        return_buf = IRnode.from_list(return_buf, typ=wrapped_return_t, location=MEMORY)
        unpacker.append(make_setter(return_buf, buf))
    else:
        return_buf = buf
    if call_kwargs.default_return_value is not None:
        override_value = wrap_value_for_external_return(call_kwargs.default_return_value)
        stomp_return_buffer = ["seq"]
        if not call_kwargs.skip_contract_check:
            stomp_return_buffer.append(_extcodesize_check(contract_address))
        stomp_return_buffer.append(make_setter(return_buf, override_value))
        unpacker = ["if", ["eq", "returndatasize", 0], stomp_return_buffer, unpacker]
    unpacker = ["seq", unpacker, return_buf]
    return unpacker, ret_ofst, ret_len
def _external_call_helper(contract_address, args_ir, call_kwargs, call_expr, context):
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    ret.append(eval_once_check(_freshname(call_expr.node_source_code)))
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
    return_t = fn_type.return_type
    if return_t is not None:
        ret.append(ret_unpacker)
    return IRnode.from_list(ret, typ=return_t, location=MEMORY)
def make_byte_array_copier(dst, src):
    assert isinstance(src.typ, _BytestringT)
    assert isinstance(dst.typ, _BytestringT)
    _check_assign_bytes(dst, src)
    if src.value == "~empty":
        return STORE(dst, 0)
    with src.cache_when_complex("src") as (b1, src):
        with get_bytearray_length(src).cache_when_complex("len") as (b2, len_):
            max_bytes = src.typ.maxlen
            ret = ["seq"]
            ret.append(STORE(dst, len_))
            dst = bytes_data_ptr(dst)
            src = bytes_data_ptr(src)
            ret.append(copy_bytes(dst, src, len_, max_bytes))
            return b1.resolve(b2.resolve(ret))
def _dynarray_make_setter(dst, src):
    assert isinstance(src.typ, DArrayT)
    assert isinstance(dst.typ, DArrayT)
    if src.value == "~empty":
        return IRnode.from_list(STORE(dst, 0))
    if src.value == "multi":
        ret = ["seq"]
        store_length = STORE(dst, len(src.args))
        ann = None
        if src.annotation is not None:
            ann = f"len({src.annotation})"
        store_length = IRnode.from_list(store_length, annotation=ann)
        ret.append(store_length)
        n_items = len(src.args)
        for i in range(n_items):
            k = IRnode.from_list(i, typ=UINT256_T)
            dst_i = get_element_ptr(dst, k, array_bounds_check=False)
            src_i = get_element_ptr(src, k, array_bounds_check=False)
            ret.append(make_setter(dst_i, src_i))
        return ret
    with src.cache_when_complex("darray_src") as (b1, src):
        should_loop = src.encoding == Encoding.ABI and src.typ.value_type.abi_type.is_dynamic()
        should_loop |= needs_clamp(src.typ.value_type, src.encoding)
        should_loop |= src.typ.value_type.abi_type.is_dynamic()
        with get_dyn_array_count(src).cache_when_complex("darray_count") as (b2, count):
            ret = ["seq"]
            ret.append(STORE(dst, count))
            if should_loop:
                i = IRnode.from_list(_freshname("copy_darray_ix"), typ=UINT256_T)
                loop_body = make_setter(
                    get_element_ptr(dst, i, array_bounds_check=False),
                    get_element_ptr(src, i, array_bounds_check=False),
                )
                loop_body.annotation = f"{dst}[i] = {src}[i]"
                ret.append(["repeat", i, 0, count, src.typ.count, loop_body])
            else:
                element_size = src.typ.value_type.memory_bytes_required
                n_bytes = _mul(count, element_size)
                max_bytes = src.typ.count * element_size
                src_ = dynarray_data_ptr(src)
                dst_ = dynarray_data_ptr(dst)
                ret.append(copy_bytes(dst_, src_, n_bytes, max_bytes))
            return b1.resolve(b2.resolve(ret))
def pop_dyn_array(darray_node, return_popped_item):
    assert isinstance(darray_node.typ, DArrayT)
    assert darray_node.encoding == Encoding.VYPER
    ret = ["seq"]
    with darray_node.cache_when_complex("darray") as (b1, darray_node):
        old_len = clamp("gt", get_dyn_array_count(darray_node), 0)
        new_len = IRnode.from_list(["sub", old_len, 1], typ=UINT256_T)
        with new_len.cache_when_complex("new_len") as (b2, new_len):
            ret.append(STORE(darray_node, new_len))
            if return_popped_item:
                popped_item = get_element_ptr(darray_node, new_len, array_bounds_check=False)
                ret.append(popped_item)
                typ = popped_item.typ
                location = popped_item.location
            else:
                typ, location = None, None
            return IRnode.from_list(b1.resolve(b2.resolve(ret)), typ=typ, location=location)
