def to_path(value):
    """
    Converts values to a property path array.
    Args:
        value (mixed): Value to convert.
    Returns:
        list: Returns the new property path array.
    Example:
        >>> to_path('a.b.c')
        ['a', 'b', 'c']
        >>> to_path('a[0].b.c')
        ['a', 0, 'b', 'c']
        >>> to_path('a[0][1][2].b.c')
        ['a', 0, 1, 2, 'b', 'c']
