                        subtype=get_dataset_storetype(the_store.resource_type),
                        alternate=f"{workspace.name}:{resource.name}",
                        title=resource.title or _("No title provided"),
                        abstract=resource.abstract or _("No abstract provided"),
                        owner=owner,
                    ),
                )
