            created = tz.utcfromtimestamp(info.st_ctime)
        except (ValueError, OSError):
            self.log.warning("Invalid ctime %s for %s", info.st_ctime, os_path)
            created = datetime(1970, 1, 1, 0, 0, tzinfo=tz.UTC)
