        Parameters
        ----------
        path : str
            The path to check. This is an API path (`/` separated,
            relative to root_dir).
        Returns
        -------
        hidden : bool
            Whether the path exists and is hidden.
        """
        path = path.strip("/")
        os_path = self._get_os_path(path=path)
        return is_hidden(os_path, self.root_dir)
