class Shares:
    def file_is_shared(self, user, virtualfilename, realfilename):
        log.add_transfer("Checking if file %(virtual_name)s with real path %(path)s is shared", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        if not os.access(realfilename, os.R_OK):
            log.add_transfer("Can't access file %(virtual_name)s with real path %(path)s, not sharing", {
                "virtual_name": virtualfilename,
                "path": realfilename
            })
            return False
        folder, _sep, file = virtualfilename.rpartition('\\')
        shared = self.share_dbs.get("files")
        bshared = self.share_dbs.get("buddyfiles")
        if bshared is not None:
            for row in self.config.sections["server"]["userlist"]:
                if row[0] != user:
                    continue
                if self.config.sections["transfers"]["buddysharestrustedonly"] and not row[4]:
                    break
                for fileinfo in bshared.get(str(folder), ""):
                    if file == fileinfo[0]:
                        return True
        if shared is not None:
            for fileinfo in shared.get(str(folder), ""):
                if file == fileinfo[0]:
                    return True
        log.add_transfer("Failed to share file %(virtual_name)s with real path %(path)s, since it wasn't found", {
            "virtual_name": virtualfilename,
            "path": realfilename
        })
        return False
def open_file_path(file_path, command=None):
    """ Currently used to either open a folder or play an audio file
    Tries to run a user-specified command first, and falls back to
    the system default. """
    try:
        file_path = os.path.normpath(file_path)
        if command and "$" in command:
            execute_command(command, file_path)
        elif sys.platform == "win32":
            os.startfile(file_path)
        elif sys.platform == "darwin":
            execute_command("open $", file_path)
        elif not webbrowser.open(file_path):
            raise webbrowser.Error("no known URL provider available")
    except Exception as error:
        log.add(_("Failed to open file path: %s"), error)
def open_uri(uri):
    """ Open a URI in an external (web) browser. The given argument has
    to be a properly formed URI including the scheme (fe. HTTP). """
    protocol = uri[:uri.find(":")]
    protocol_handlers = config.sections["urls"]["protocols"]
    if protocol in protocol_handlers and protocol_handlers[protocol]:
        try:
            execute_command(protocol_handlers[protocol], uri)
            return True
        except RuntimeError as error:
            log.add(error)
    if protocol == "slsk":
        OPEN_SOULSEEK_URL(uri.strip())
        return True
    try:
        if not webbrowser.open(uri):
            raise webbrowser.Error("no known URL provider available")
        return True
    except Exception as error:
        log.add(_("Failed to open URL: %s"), error)
    return False
def execute_command(command, replacement=None, background=True, returnoutput=False, placeholder='$'):
    """Executes a string with commands, with partial support for bash-style quoting and pipes.
    The different parts of the command should be separated by spaces, a double
    quotation mark can be used to embed spaces in an argument.
    Pipes can be created using the bar symbol (|).
    If background is false the function will wait for all the launched
    processes to end before returning.
    If the 'replacement' argument is given, every occurance of 'placeholder'
    will be replaced by 'replacement'.
    If the command ends with the ampersand symbol background
    will be set to True. This should only be done by the request of the user,
    if you want background to be true set the function argument.
    The only expected error to be thrown is the RuntimeError in case something
    goes wrong while executing the command.
    Example commands:
    * "C:\\Program Files\\WinAmp\\WinAmp.exe" --xforce "--title=My Window Title"
    * mplayer $
    * echo $ | flite -t """
    from subprocess import PIPE
    from subprocess import Popen
    if returnoutput:
        background = False
    command = command.strip()
    if command.endswith("&"):
        command = command[:-1]
        if returnoutput:
            log.add("Yikes, I was asked to return output but I'm also asked to launch "
                    "the process in the background. returnoutput gets precedent.")
        else:
            background = True
    unparsed = command
    arguments = []
    while unparsed.count('"') > 1:
        (pre, argument, post) = unparsed.split('"', 2)
        if pre:
            arguments += pre.rstrip(' ').split(' ')
        arguments.append(argument)
        unparsed = post.lstrip(' ')
    if unparsed:
        arguments += unparsed.split(' ')
    subcommands = []
    current = []
    for argument in arguments:
        if argument in ('|',):
            subcommands.append(current)
            current = []
        else:
            current.append(argument)
    subcommands.append(current)
    if replacement:
        for i, _ in enumerate(subcommands):
            subcommands[i] = [x.replace(placeholder, replacement) for x in subcommands[i]]
    finalstdout = None
    if returnoutput:
        finalstdout = PIPE
    procs = []
    try:
        if len(subcommands) == 1:
            procs.append(Popen(subcommands[0], stdout=finalstdout))
        else:
            procs.append(Popen(subcommands[0], stdout=PIPE))
            for subcommand in subcommands[1:-1]:
                procs.append(Popen(subcommand, stdin=procs[-1].stdout, stdout=PIPE))
            procs.append(Popen(subcommands[-1], stdin=procs[-1].stdout, stdout=finalstdout))
        if not background and not returnoutput:
            procs[-1].wait()
    except Exception as error:
        raise RuntimeError("Problem while executing command %s (%s of %s)" %
                           (subcommands[len(procs)], len(procs) + 1, len(subcommands))) from error
    if not returnoutput:
        return True
    return procs[-1].communicate()[0]
class Transfers:
    def queue_upload(self, msg):
        """ Peer remotely queued a download (upload here). This is the modern replacement to
        a TransferRequest with direction 0 (download request). We will initiate the upload of
        the queued file later. """
        user = msg.conn.init.target_user
        addr = msg.conn.addr[0]
        real_path = self.core.shares.virtual2real(msg.file)
        if not self.file_is_upload_queued(user, msg.file):
            limits = True
            if self.config.sections["transfers"]["friendsnolimits"]:
                friend = user in (i[0] for i in self.config.sections["server"]["userlist"])
                if friend:
                    limits = False
            checkuser, reason = self.core.network_filter.check_user(user, addr)
            if not checkuser:
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason=reason)
                )
            elif limits and self.queue_limit_reached(user):
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="Too many megabytes")
                )
            elif limits and self.file_limit_reached(user):
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="Too many files")
                )
            elif self.core.shares.file_is_shared(user, msg.file, real_path):
                newupload = Transfer(
                    user=user, filename=msg.file,
                    path=os.path.dirname(real_path), status="Queued",
                    timequeued=time.time(), size=self.get_file_size(real_path)
                )
                self._append_upload(user, msg.file, newupload)
                if self.uploadsview:
                    self.uploadsview.update(newupload)
                self.core.pluginhandler.upload_queued_notification(user, msg.file, real_path)
                self.check_upload_queue()
            else:
                self.queue.append(
                    slskmessages.UploadDenied(conn=msg.conn.conn, file=msg.file, reason="File not shared.")
                )
        log.add_transfer("QueueUpload request: User %(user)s, %(msg)s", {
            'user': user,
            'msg': str(vars(msg))
        })
    def _file_request_download(self, msg, i):
        log.add_transfer("Received file upload request %(request)s for file %(filename)s from user %(user)s", {
            "request": msg.req,
            "filename": i.filename,
            "user": i.user
        })
        incompletedir = self.config.sections["transfers"]["incompletedir"]
        needupdate = True
        if i.conn is None and i.size is not None:
            i.conn = msg.conn
            i.req = None
            if i in self.transfer_request_times:
                del self.transfer_request_times[i]
            if not incompletedir:
                if i.path:
                    incompletedir = i.path
                else:
                    incompletedir = self.get_default_download_folder(i.user)
            try:
                if not os.access(incompletedir, os.F_OK):
                    os.makedirs(incompletedir)
                if not os.access(incompletedir, os.R_OK | os.W_OK | os.X_OK):
                    raise OSError("Download directory %s Permissions error.\nDir Permissions: %s" %
                                  (incompletedir, oct(os.stat(incompletedir)[stat.ST_MODE] & 0o777)))
            except OSError as error:
                log.add(_("OS error: %s"), error)
                self.download_folder_error(i, error)
            else:
                file_handle = None
                try:
                    from hashlib import md5
                    md5sum = md5()
                    md5sum.update((i.filename + i.user).encode('utf-8'))
                    base_name = clean_file(i.filename.replace('/', '\\').split('\\')[-1])
                    incomplete_name = os.path.join(incompletedir, "INCOMPLETE" + md5sum.hexdigest() + base_name)
                    file_handle = open(incomplete_name, 'ab+')
                    if self.config.sections["transfers"]["lock"]:
                        try:
                            import fcntl
                            try:
                                fcntl.lockf(file_handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
                            except IOError as error:
                                log.add(_("Can't get an exclusive lock on file - I/O error: %s"), error)
                        except ImportError:
                            pass
                    file_handle.seek(0, 2)
                    offset = file_handle.tell()
                except IOError as error:
                    log.add(_("Download I/O error: %s"), error)
                    self.abort_transfer(i)
                    i.status = "Local file error"
                else:
                    i.file = file_handle
                    i.lastbytes = offset
                    i.place = 0
                    self.core.statistics.append_stat_value("started_downloads", 1)
                    self.core.pluginhandler.download_started_notification(i.user, i.filename, incomplete_name)
                    if i.size > offset:
                        i.status = "Transferring"
                        i.legacy_attempt = False
                        self.queue.append(slskmessages.DownloadFile(i.conn, file_handle))
                        self.queue.append(slskmessages.FileOffset(i.conn, i.size, offset))
                        log.add_download(
                            _("Download started: user %(user)s, file %(file)s"), {
                                "user": i.user,
                                "file": "%s" % file_handle.name
                            }
                        )
                    else:
                        self.download_finished(file_handle, i)
                        needupdate = False
            if self.downloadsview:
                self.downloadsview.new_transfer_notification()
                if needupdate:
                    self.downloadsview.update(i)
        else:
            log.add_transfer("Download error formally known as 'Unknown file request': %(req)s (%(user)s: %(file)s)", {
                'req': str(vars(msg)),
                'user': i.user,
                'file': i.filename
            })
            self.queue.append(slskmessages.ConnClose(msg.conn))
    def _file_request_upload(self, msg, i):
        log.add_transfer("Received file download request %(request)s for file %(filename)s from user %(user)s", {
            "request": msg.req,
            "filename": i.filename,
            "user": i.user
        })
        needupdate = True
        if i.conn is None:
            i.conn = msg.conn
            i.req = None
            file_handle = None
            if i in self.transfer_request_times:
                del self.transfer_request_times[i]
            try:
                real_path = self.core.shares.virtual2real(i.filename)
                file_handle = open(real_path, "rb")
                offset = file_handle.tell()
            except IOError as error:
                log.add(_("Upload I/O error: %s"), error)
                self.abort_transfer(i)
                i.status = "Local file error"
                self.check_upload_queue()
            else:
                i.file = file_handle
                i.lastbytes = offset
                i.place = 0
                self.core.statistics.append_stat_value("started_uploads", 1)
                self.core.pluginhandler.upload_started_notification(i.user, i.filename, real_path)
                if i.size > offset:
                    i.status = "Transferring"
                    self.queue.append(slskmessages.UploadFile(i.conn, file=file_handle, size=i.size))
                    ip_address = None
                    if i.conn is not None:
                        try:
                            ip_address = i.conn.getpeername()
                        except OSError:
                            pass
                    log.add_upload(
                        _("Upload started: user %(user)s, IP address %(ip)s, file %(file)s"), {
                            "user": i.user,
                            "ip": ip_address,
                            "file": i.filename
                        }
                    )
                else:
                    i.lasttime = time.time()
                    self.upload_finished(i, file_handle=file_handle)
                    needupdate = False
            if self.uploadsview:
                self.uploadsview.new_transfer_notification()
                if needupdate:
                    self.uploadsview.update(i)
        else:
            log.add_transfer("Upload error formally known as 'Unknown file request': %(req)s (%(user)s: %(file)s)", {
                'req': str(vars(msg)),
                'user': i.user,
                'file': i.filename
            })
            self.queue.append(slskmessages.ConnClose(msg.conn))
    def get_file(self, user, filename, path="", transfer=None, size=None, bitrate=None, length=None):
        path = clean_path(path, absolute=True)
        if transfer is None:
            for i in self.downloads:
                if i.user == user and i.filename == filename and i.path == path:
                    if i.status == "Finished":
                        transfer = i
                        break
                    return
            transfer = Transfer(
                user=user, filename=filename, path=path,
                status="Queued", size=size, bitrate=bitrate,
                length=length
            )
            self.downloads.appendleft(transfer)
        else:
            transfer.filename = filename
            transfer.status = "Queued"
        self.core.watch_user(user)
        if self.config.sections["transfers"]["enablefilters"]:
            try:
                downloadregexp = re.compile(self.config.sections["transfers"]["downloadregexp"], re.I)
                if downloadregexp.search(filename) is not None:
                    log.add_transfer("Filtering: %s", filename)
                    self.abort_transfer(transfer)
                    transfer.status = "Filtered"
                    if self.auto_clear_download(transfer):
                        return
            except Exception:
                pass
        if self.user_logged_out(user):
            transfer.status = "User logged off"
        elif transfer.status != "Filtered":
            download_path = self.get_existing_download_path(user, filename, path, size)
            if download_path:
                transfer.status = "Finished"
                transfer.size = transfer.currentbytes = size
                log.add_transfer("File %s is already downloaded", download_path)
            else:
                log.add_transfer("Adding file %(filename)s from user %(user)s to download queue", {
                    "filename": filename,
                    "user": user
                })
                self.core.send_message_to_peer(
                    user, slskmessages.QueueUpload(None, filename, transfer.legacy_attempt))
        if self.downloadsview:
            self.downloadsview.update(transfer)
    def push_file(self, user, filename, size, path="", transfer=None, bitrate=None, length=None, locally_queued=False):
        if not self.core.logged_in:
            return
        real_path = self.core.shares.virtual2real(filename)
        size_attempt = self.get_file_size(real_path)
        if size_attempt > 0:
            size = size_attempt
        if transfer is None:
            transfer = Transfer(
                user=user, filename=filename, path=path,
                status="Queued", size=size, bitrate=bitrate,
                length=length
            )
            self._append_upload(user, filename, transfer)
        else:
            transfer.filename = filename
            transfer.size = size
            transfer.status = "Queued"
        log.add_transfer(
            "Initializing upload request for file %(file)s to user %(user)s", {
                'file': filename,
                'user': user
            }
        )
        self.core.watch_user(user)
        if self.user_logged_out(user):
            transfer.status = "User logged off"
        elif not locally_queued:
            transfer.req = self.core.get_new_token()
            transfer.status = "Getting status"
            self.transfer_request_times[transfer] = time.time()
            log.add_transfer("Requesting to upload file %(filename)s with transfer "
                             + "request %(request)s to user %(user)s", {
                                 "filename": filename,
                                 "request": transfer.req,
                                 "user": user
                             })
            self.core.send_message_to_peer(
                user, slskmessages.TransferRequest(None, 1, transfer.req, filename, size, real_path))
        if self.uploadsview:
            self.uploadsview.update(transfer)
    def download_finished(self, file, i):
        self.close_file(file, i)
        folder, basename = self.get_download_destination(i.user, i.filename, i.path)
        newname = self.get_renamed(os.path.join(folder, basename))
        try:
            if not os.access(folder, os.F_OK):
                os.makedirs(folder)
            import shutil
            shutil.move(file.name, newname)
        except (IOError, OSError) as inst:
            log.add(
                _("Couldn't move '%(tempfile)s' to '%(file)s': %(error)s"), {
                    'tempfile': "%s" % file.name,
                    'file': newname,
                    'error': inst
                }
            )
            self.download_folder_error(i, inst)
            if self.downloadsview:
                self.downloadsview.update(i)
            return
        i.status = "Finished"
        i.currentbytes = i.size
        i.speed = None
        i.timeleft = ""
        i.conn = None
        self.core.statistics.append_stat_value("completed_downloads", 1)
        self.file_downloaded_actions(i.user, newname)
        self.folder_downloaded_actions(i.user, i.path)
        if self.downloadsview:
            self.downloadsview.new_transfer_notification(finished=True)
            if not self.auto_clear_download(i):
                self.downloadsview.update(i)
        self.core.pluginhandler.download_finished_notification(i.user, i.filename, newname)
        self.save_transfers("downloads")
        log.add_download(
            _("Download finished: user %(user)s, file %(file)s"), {
                'user': i.user,
                'file': i.filename
            }
        )
    def abort_transfer(self, transfer, reason="Cancelled", send_fail_message=False):
        transfer.legacy_attempt = False
        transfer.req = None
        transfer.speed = None
        transfer.place = 0
        transfer.timeleft = ""
        if transfer.conn is not None:
            self.queue.append(slskmessages.ConnClose(transfer.conn))
            transfer.conn = None
        if transfer in self.transfer_request_times:
            del self.transfer_request_times[transfer]
        if transfer.file is not None:
            self.close_file(transfer.file, transfer)
            if transfer in self.uploads:
                self.check_upload_queue()
                log.add_upload(
                    _("Upload aborted, user %(user)s file %(file)s"), {
                        "user": transfer.user,
                        "file": transfer.filename
                    }
                )
            else:
                log.add_download(
                    _("Download aborted, user %(user)s file %(file)s"), {
                        "user": transfer.user,
                        "file": transfer.filename
                    }
                )
        elif send_fail_message and transfer in self.uploads and transfer.status == "Queued":
            self.core.send_message_to_peer(
                transfer.user, slskmessages.UploadDenied(None, file=transfer.filename, reason=reason))
class SSDPRequest:
    def sendto(self, sock, addr):
        msg = bytes(self)
        sock.sendto(msg, addr)
        log.add_debug("UPnP: SSDP request: %s", msg)
class SSDP:
    @staticmethod
    def get_routers(private_ip=None):
        log.add_debug("UPnP: Discovering... delay=%s seconds", SSDP.response_time_secs)
        sock = socket.socket(family=socket.AF_INET, type=socket.SOCK_DGRAM, proto=socket.IPPROTO_UDP)
        sock.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, SSDP.response_time_secs)
        sock.setblocking(False)
        if private_ip:
            sock.bind((private_ip, 0))
        wan_ip1_sent = False
        wan_ip1 = SSDPRequest("urn:schemas-upnp-org:service:WANIPConnection:1")
        wan_ppp1_sent = False
        wan_ppp1 = SSDPRequest("urn:schemas-upnp-org:service:WANPPPConnection:1")
        wan_igd1_sent = False
        wan_igd1 = SSDPRequest("urn:schemas-upnp-org:device:InternetGatewayDevice:1")
        wan_ip2_sent = False
        wan_ip2 = SSDPRequest("urn:schemas-upnp-org:service:WANIPConnection:2")
        wan_igd2_sent = False
        wan_igd2 = SSDPRequest("urn:schemas-upnp-org:device:InternetGatewayDevice:2")
        routers = []
        time_end = time.time() + SSDP.response_time_secs
        while time.time() < time_end:
            readable, writable, _ = select.select([sock], [sock], [sock], 0)
            for sock in readable:
                msg, _sender = sock.recvfrom(4096)
                SSDP.add_router(routers, SSDPResponse(msg.decode('utf-8')))
            for sock in writable:
                if not wan_ip1_sent:
                    wan_ip1.sendto(sock, (SSDP.multicast_host, SSDP.multicast_port))
                    log.add_debug("UPnP: Sent M-SEARCH IP request 1")
                    time_end = time.time() + SSDP.response_time_secs
                    wan_ip1_sent = True
                if not wan_ppp1_sent:
                    wan_ppp1.sendto(sock, (SSDP.multicast_host, SSDP.multicast_port))
                    log.add_debug("UPnP: Sent M-SEARCH PPP request 1")
                    time_end = time.time() + SSDP.response_time_secs
                    wan_ppp1_sent = True
                if not wan_igd1_sent:
                    wan_igd1.sendto(sock, (SSDP.multicast_host, SSDP.multicast_port))
                    log.add_debug("UPnP: Sent M-SEARCH IGD request 1")
                    time_end = time.time() + SSDP.response_time_secs
                    wan_igd1_sent = True
                if not wan_ip2_sent:
                    wan_ip2.sendto(sock, (SSDP.multicast_host, SSDP.multicast_port))
                    log.add_debug("UPnP: Sent M-SEARCH IP request 2")
                    time_end = time.time() + SSDP.response_time_secs
                    wan_ip2_sent = True
                if not wan_igd2_sent:
                    wan_igd2.sendto(sock, (SSDP.multicast_host, SSDP.multicast_port))
                    log.add_debug("UPnP: Sent M-SEARCH IGD request 2")
                    time_end = time.time() + SSDP.response_time_secs
                    wan_igd2_sent = True
            time.sleep(0.01)
        log.add_debug("UPnP: %s device(s) detected", str(len(routers)))
        sock.close()
        return routers
class UPnPPortMapping:
    def add_port_mapping(self, router, protocol, public_port, private_ip, private_port,
                         mapping_description, lease_duration):
        """
        Function that adds a port mapping to the router.
        If a port mapping already exists, it is updated with a lease period of 24 hours.
        """
        from xml.etree import ElementTree
        url = '%s%s' % (router.base_url, router.control_url)
        log.add_debug("UPnP: Adding port mapping (%s %s/%s, %s) at url '%s'",
                      (private_ip, private_port, protocol, router.search_target, url))
        headers = {
            "Host": router.base_url,
            "Content-Type": "text/xml; charset=utf-8",
            "SOAPACTION": '"%s
        }
        body = (self.request_body % (router.service_type, public_port, protocol, private_port, private_ip,
                                     mapping_description, lease_duration)).encode('utf-8')
        log.add_debug("UPnP: Add port mapping request headers: %s", headers)
        log.add_debug("UPnP: Add port mapping request contents: %s", body)
        response = http_request(
            router.url_scheme, router.base_url, router.control_url,
            request_type="POST", body=body, headers=headers)
        xml = ElementTree.fromstring(response)
        if not xml.find(".//{http://schemas.xmlsoap.org/soap/envelope/}Body"):
            raise Exception("Invalid port mapping response: %s" % response.encode('utf-8'))
        log.add_debug("UPnP: Add port mapping response: %s", response.encode('utf-8'))
        error_code = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorCode")
        error_description = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorDescription")
        if error_code or error_description:
            raise Exception("Error code %(code)s: %(description)s" %
                            {"code": error_code, "description": error_description})
class Search:
    def __init__(self, core, config, queue, share_dbs, geoip, ui_callback=None):
        self.core = core
        self.config = config
        self.queue = queue
        self.ui_callback = None
        self.searches = {}
        self.searchid = int(random.random() * (2 ** 31 - 1))
        self.wishlist_interval = 0
        self.share_dbs = share_dbs
        self.geoip = geoip
        self.translatepunctuation = str.maketrans(dict.fromkeys(PUNCTUATION, ' '))
        for term in config.sections["server"]["autosearch"]:
            search_id = self.increment_search_id()
            self.searches[search_id] = {"id": search_id, "term": term, "mode": "wishlist", "ignore": True}
        if hasattr(ui_callback, "search"):
            self.ui_callback = ui_callback.search
    def process_search_request(self, searchterm, user, searchid, direct=False):
        """ Note: since this section is accessed every time a search request arrives,
        several times a second, please keep it as optimized and memory
        sparse as possible! """
        if not searchterm:
            return
        if not self.config.sections["searches"]["search_results"]:
            return
        if not direct and user == self.config.sections["server"]["login"]:
            return
        maxresults = self.config.sections["searches"]["maxresults"]
        if maxresults == 0:
            return
        excluded_words = []
        partial_words = []
        if '-' in searchterm or '*' in searchterm:
            for word in searchterm.split():
                if len(word) < 1:
                    continue
                if word.startswith('-'):
                    for subword in word.translate(self.translatepunctuation).split():
                        excluded_words.append(subword)
                elif word.startswith('*'):
                    for subword in word.translate(self.translatepunctuation).split():
                        partial_words.append(subword)
        searchterm_old = searchterm
        searchterm = searchterm.lower().translate(self.translatepunctuation).strip()
        if len(searchterm) < self.config.sections["searches"]["min_search_chars"]:
            return
        checkuser, _reason = self.core.network_filter.check_user(user, None)
        if not checkuser:
            return
        if checkuser == 2:
            wordindex = self.share_dbs.get("buddywordindex")
        else:
            wordindex = self.share_dbs.get("wordindex")
        if wordindex is None:
            return
        resultlist = self.create_search_result_list(searchterm, wordindex, excluded_words, partial_words)
        if not resultlist:
            return
        if checkuser == 2:
            fileindex = self.share_dbs.get("buddyfileindex")
        else:
            fileindex = self.share_dbs.get("fileindex")
        if fileindex is None:
            return
        fileinfos = []
        numresults = min(len(resultlist), maxresults)
        for index in islice(resultlist, numresults):
            fileinfo = fileindex.get(repr(index))
            if fileinfo is not None:
                fileinfos.append(fileinfo)
        if numresults != len(fileinfos):
            log.add_debug(("File index inconsistency while responding to search request "
                           "\"%(query)s\". %(expected_num)s results expected, but only %(total_num)s "
                           "results were found in database."), {
                "query": searchterm_old,
                "expected_num": numresults,
                "total_num": len(fileinfos)
            })
        numresults = len(fileinfos)
        if not numresults:
            return
        uploadspeed = self.core.transfers.upload_speed
        queuesize = self.core.transfers.get_upload_queue_size()
        slotsavail = self.core.transfers.allow_new_uploads()
        fifoqueue = self.config.sections["transfers"]["fifoqueue"]
        message = slskmessages.FileSearchResult(
            None, self.config.sections["server"]["login"],
            searchid, fileinfos, slotsavail, uploadspeed, queuesize, fifoqueue)
        self.core.send_message_to_peer(user, message)
        if direct:
            log.add_search(
                _("User %(user)s is directly searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
        else:
            log.add_search(
                _("User %(user)s is searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
class NicotineCore:
    def send_message_to_peer(self, user, message, address=None):
        """ Sends message to a peer. Used primarily when we know the username of a peer,
        but don't have an active connection. """
        conn = None
        if message.__class__ is not slskmessages.FileRequest:
            """ Check if there's already a connection object for the specified username """
            for i in self.peerconns:
                if i.username == user and i.conn_type == 'P':
                    conn = i
                    log.add_conn("Found existing connection of type %(type)s for user %(user)s, using it.", {
                        'type': i.conn_type,
                        'user': user
                    })
                    break
        if conn is not None and conn.conn is not None:
            """ We have initiated a connection previously, and it's ready """
            conn.msgs.append(message)
            self.process_conn_messages(conn, conn.conn)
        elif conn is not None:
            """ Connection exists but is not ready yet, add new messages to it """
            conn.msgs.append(message)
        else:
            """ This is a new peer, initiate a connection """
            self.initiate_connection_to_peer(user, message, address)
        log.add_conn("Sending message of type %(type)s to user %(user)s", {
            'type': message.__class__,
            'user': user
        })
    def login(self, msg):
        """ Server code: 1 """
        log.add_msg_contents(msg)
        if msg.success:
            self.exit.clear()
            thread = threading.Thread(target=self._check_indirect_connection_timeouts)
            thread.name = "IndirectConnectionTimeoutTimer"
            thread.daemon = True
            thread.start()
            self.logged_in = True
            self.set_away_mode(config.sections["server"]["away"])
            self.watch_user(config.sections["server"]["login"])
            if msg.ip_address is not None:
                self.user_ip_address = msg.ip_address
            self.transfers.server_login()
            self.userbrowse.server_login()
            self.userinfo.server_login()
            self.userlist.server_login()
            self.privatechats.server_login()
            self.chatrooms.server_login()
            if self.ui_callback:
                self.ui_callback.server_login()
            if msg.banner:
                log.add(msg.banner)
            self.interests.server_login()
            self.queue.append(slskmessages.CheckPrivileges())
            self.send_have_no_parent()
            """ TODO: We can currently receive search requests from a parent connection, but
            redirecting results to children is not implemented yet. Tell the server we don't accept
            children for now. """
            self.queue.append(slskmessages.AcceptChildren(0))
            self.shares.send_num_shared_folders_files()
            """ Request a complete room list. A limited room list not including blacklisted rooms and
            rooms with few users is automatically sent when logging in, but subsequent room list
            requests contain all rooms. """
            self.queue.append(slskmessages.RoomList())
            self.queue.append(slskmessages.PrivateRoomToggle(config.sections["server"]["private_chatrooms"]))
            self.pluginhandler.server_connect_notification()
        else:
            self.manual_disconnect = True
            self.queue.append(slskmessages.ConnClose(self.server_conn))
            if msg.reason == "INVALIDPASS":
                self.ui_callback.invalid_password()
                return
            log.add_important_error(_("Unable to connect to the server. Reason: %s"), msg.reason)
class SlskProtoThread(threading.Thread):
    def process_conn_input(self, connection, conn_obj):
        if connection is self.server_socket:
            self.process_server_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is None:
            self.process_peer_init_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'P':
            self.process_peer_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'F':
            self.process_file_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'D':
            self.process_distrib_input(conn_obj, conn_obj.ibuf)
        else:
            log.add("Can't handle connection type %s", conn_obj.init.conn_type)
    def run(self):
        self.selector.register(self.listen_socket, selectors.EVENT_READ)
        while not self._want_abort:
            if self.server_disconnected:
                time.sleep(0.1)
                continue
            curtime = time.time()
            if (curtime - self.last_conncount_callback) > self.CONNCOUNT_CALLBACK_INTERVAL:
                self._callback_msgs.append(SetCurrentConnectionCount(self._numsockets))
                self.last_conncount_callback = curtime
            if self._queue:
                self.process_conn_output()
            try:
                key_events = self.selector.select(timeout=-1)
                input_list = set(key.fileobj for key, event in key_events if event & selectors.EVENT_READ)
                output_list = set(key.fileobj for key, event in key_events if event & selectors.EVENT_WRITE)
            except OSError as error:
                log.add("Major Socket Error: Networking terminated! %s", error)
                self._want_abort = True
            except ValueError as error:
                log.add("select ValueError: %s", error)
                time.sleep(0.1)
                self._callback_msgs.clear()
                continue
            if self._numsockets < MAXSOCKETS and not self.server_disconnected and self.listen_socket in input_list:
                try:
                    incconn, incaddr = self.listen_socket.accept()
                except Exception:
                    time.sleep(0.01)
                else:
                    if self._network_filter.is_ip_blocked(incaddr[0]):
                        log.add_conn("Ignoring connection request from blocked IP address %(ip)s:%(port)s", {
                            'ip': incaddr[0],
                            'port': incaddr[1]
                        })
                        incconn.close()
                    else:
                        events = selectors.EVENT_READ
                        incconn.setblocking(0)
                        self._conns[incconn] = PeerConnection(conn=incconn, addr=incaddr, events=events)
                        self._numsockets += 1
                        self._callback_msgs.append(IncConn(incconn, incaddr))
                        self.selector.register(incconn, events)
            for connection_in_progress in self._connsinprogress.copy():
                try:
                    conn_obj = self._connsinprogress[connection_in_progress]
                except KeyError:
                    continue
                msg_obj = conn_obj.msg_obj
                if (curtime - conn_obj.lastactive) > self.IN_PROGRESS_STALE_AFTER:
                    self._callback_msgs.append(ConnectError(msg_obj, "Timed out"))
                    self.close_connection(self._connsinprogress, connection_in_progress)
                    continue
                try:
                    if connection_in_progress in input_list:
                        connection_in_progress.recv(1, socket.MSG_PEEK)
                except socket.error as err:
                    self._callback_msgs.append(ConnectError(msg_obj, err))
                    self.close_connection(self._connsinprogress, connection_in_progress)
                else:
                    if connection_in_progress in output_list:
                        addr = msg_obj.addr
                        events = selectors.EVENT_READ | selectors.EVENT_WRITE
                        if connection_in_progress is self.server_socket:
                            self._conns[self.server_socket] = Connection(
                                conn=self.server_socket, addr=addr, events=events)
                            self._callback_msgs.append(InitServerConn(self.server_socket, addr))
                        else:
                            if self._network_filter.is_ip_blocked(addr[0]):
                                log.add_conn("Ignoring connection request from blocked IP address %(ip)s:%(port)s", {
                                    "ip": addr[0],
                                    "port": addr[1]
                                })
                                self._callback_msgs.append(ConnectError(msg_obj, "Blocked IP address"))
                                self.close_connection(self._connsinprogress, connection_in_progress)
                                continue
                            self._conns[connection_in_progress] = PeerConnection(
                                conn=connection_in_progress, addr=addr, events=events, init=msg_obj.init)
                            self._callback_msgs.append(InitPeerConn(connection_in_progress, addr))
                        del self._connsinprogress[connection_in_progress]
            for connection in self._conns.copy():
                try:
                    conn_obj = self._conns[connection]
                except KeyError:
                    continue
                if (connection is not self.server_socket
                        and (curtime - conn_obj.lastactive) > self.CONNECTION_MAX_IDLE):
                    self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                    self.close_connection(self._conns, connection)
                    continue
                if connection in input_list:
                    if self._is_download(conn_obj):
                        self.set_conn_speed_limit(connection, self._download_limit_split, self._dlimits)
                    try:
                        if not self.read_data(conn_obj):
                            self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                            self.close_connection(self._conns, connection)
                            continue
                    except socket.error as err:
                        log.add_conn(("Cannot read data from connection %(addr)s, closing connection. "
                                      "Error: %(error)s"), {
                            "addr": conn_obj.addr,
                            "error": err
                        })
                        self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                        self.close_connection(self._conns, connection)
                        continue
                if conn_obj.ibuf:
                    self.process_conn_input(connection, conn_obj)
                if connection in output_list:
                    if self._is_upload(conn_obj):
                        self.set_conn_speed_limit(connection, self._upload_limit_split, self._ulimits)
                    try:
                        self.write_data(conn_obj)
                    except Exception as err:
                        log.add_conn("Cannot write data to connection %(addr)s, closing connection. Error: %(error)s", {
                            "addr": conn_obj.addr,
                            "error": err
                        })
                        self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                        self.close_connection(self._conns, connection)
                        continue
            if self._callback_msgs:
                self._core_callback(list(self._callback_msgs))
                self._callback_msgs.clear()
            self._ulimits = {}
            self._dlimits = {}
            self._calc_loops_per_second()
            time.sleep(1 / 60)
class SlskMessage:
    def get_object(self, message, obj_type, start=0, getsignedint=False, getunsignedlonglong=False):
        """ Returns object of specified type, extracted from message (which is
        a binary array). start is an offset."""
        try:
            if obj_type is int:
                if getsignedint:
                    return INT_SIZE + start, INT_UNPACK(message[start:start + INT_SIZE])[0]
                if getunsignedlonglong:
                    try:
                        return INT64_SIZE + start, UINT64_UNPACK(message[start:start + INT64_SIZE])[0]
                    except Exception:
                        pass
                return INT_SIZE + start, UINT_UNPACK(message[start:start + INT_SIZE])[0]
            if obj_type is bytes:
                length = UINT_UNPACK(message[start:start + INT_SIZE])[0]
                content = message[start + INT_SIZE:start + length + INT_SIZE]
                return length + INT_SIZE + start, content
            if obj_type is str:
                length = UINT_UNPACK(message[start:start + INT_SIZE])[0]
                string = message[start + INT_SIZE:start + length + INT_SIZE]
                try:
                    string = str(string, "utf-8")
                except Exception:
                    try:
                        string = str(string, "latin-1")
                    except Exception as error:
                        log.add("Error trying to decode string '%s': %s", (string, error))
                return length + INT_SIZE + start, string
            return start, None
        except struct.error as error:
            log.add("%s %s trying to unpack %s at '%s' at %s/%s",
                    (self.__class__, error, obj_type, bytes(message[start:]), start, len(message)))
            raise struct.error(error)
