class Scanner:
    def set_shares(self, share_type, files=None, streams=None, mtimes=None, wordindex=None):
        self.config.create_data_folder()
        storable_objects = [
            (files, "files"),
            (streams, "streams"),
            (mtimes, "mtimes"),
            (wordindex, "wordindex")
        ]
        for source, destination in storable_objects:
            if source is None:
                continue
            try:
                if share_type == "buddy":
