            self.searches[search_id] = {"id": search_id, "term": term, "mode": "wishlist", "ignore": True}
        if hasattr(ui_callback, "search"):
            self.ui_callback = ui_callback.search
    def process_search_request(self, searchterm, user, searchid, direct=False):
        """ Note: since this section is accessed every time a search request arrives,
        several times a second, please keep it as optimized and memory
        sparse as possible! """
        if not searchterm:
            return
        if not self.config.sections["searches"]["search_results"]:
            return
        if not direct and user == self.config.sections["server"]["login"]:
            return
        maxresults = self.config.sections["searches"]["maxresults"]
        if maxresults == 0:
            return
        excluded_words = []
        partial_words = []
        if '-' in searchterm or '*' in searchterm:
            for word in searchterm.split():
                if len(word) < 1:
                    continue
                if word.startswith('-'):
                    for subword in word.translate(self.translatepunctuation).split():
                        excluded_words.append(subword)
                elif word.startswith('*'):
                    for subword in word.translate(self.translatepunctuation).split():
                        partial_words.append(subword)
        searchterm_old = searchterm
        searchterm = searchterm.lower().translate(self.translatepunctuation).strip()
        if len(searchterm) < self.config.sections["searches"]["min_search_chars"]:
            return
        checkuser, _reason = self.core.network_filter.check_user(user, None)
        if not checkuser:
            return
        if checkuser == 2:
            wordindex = self.share_dbs.get("buddywordindex")
        else:
            wordindex = self.share_dbs.get("wordindex")
        if wordindex is None:
            return
        resultlist = self.create_search_result_list(searchterm, wordindex, excluded_words, partial_words)
        if not resultlist:
            return
        if checkuser == 2:
            fileindex = self.share_dbs.get("buddyfileindex")
        else:
            fileindex = self.share_dbs.get("fileindex")
        if fileindex is None:
            return
        fileinfos = []
        numresults = min(len(resultlist), maxresults)
        for index in islice(resultlist, numresults):
            fileinfo = fileindex.get(repr(index))
            if fileinfo is not None:
                fileinfos.append(fileinfo)
        if numresults != len(fileinfos):
            log.add_debug(("File index inconsistency while responding to search request "
                           "\"%(query)s\". %(expected_num)s results expected, but only %(total_num)s "
                           "results were found in database."), {
                "query": searchterm_old,
                "expected_num": numresults,
                "total_num": len(fileinfos)
            })
        numresults = len(fileinfos)
        if not numresults:
            return
        uploadspeed = self.core.transfers.upload_speed
        queuesize = self.core.transfers.get_upload_queue_size()
        slotsavail = self.core.transfers.allow_new_uploads()
        fifoqueue = self.config.sections["transfers"]["fifoqueue"]
        message = slskmessages.FileSearchResult(
            None, self.config.sections["server"]["login"],
            searchid, fileinfos, slotsavail, uploadspeed, queuesize, fifoqueue)
        self.core.send_message_to_peer(user, message)
        if direct:
            log.add_search(
                _("User %(user)s is directly searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
        else:
            log.add_search(
                _("User %(user)s is searching for \"%(query)s\", returning %(num)i results"), {
                    'user': user,
                    'query': searchterm_old,
                    'num': numresults
                })
class SlskProtoThread(threading.Thread):
    def process_peer_init_input(self, conn, msg_buffer):
        msg_buffer_mem = memoryview(msg_buffer)
        buffer_len = len(msg_buffer_mem)
        idx = 0
        while buffer_len >= 8 and conn.init is None:
            msgsize = UINT_UNPACK(msg_buffer_mem[idx:idx + 4])[0]
            msgsize_total = msgsize + 4
            if msgsize_total > buffer_len or msgsize < 0:
                break
            msgtype = msg_buffer_mem[idx + 4]
            if msgtype in self.peerinitclasses:
                msg = self.unpack_network_message(
                    self.peerinitclasses[msgtype], msg_buffer_mem[idx + 5:idx + msgsize_total], msgsize - 1,
                    "peer init", conn)
                if msg is not None:
                    if self.peerinitclasses[msgtype] is PierceFireWall:
                        conn.piercefw = msg
                    elif self.peerinitclasses[msgtype] is PeerInit:
                        conn.init = msg
                    self._callback_msgs.append(msg)
            else:
                if conn.piercefw is None:
                    log.add("Peer init message type %(type)i size %(size)i contents %(msg_buffer)s unknown",
                            {'type': msgtype, 'size': msgsize - 1,
                             'msg_buffer': msg_buffer[idx + 5:idx + msgsize_total]})
                    self._callback_msgs.append(ConnClose(conn.conn, conn.addr))
                    self.close_connection(self._conns, conn)
                break
            idx += msgsize_total
            buffer_len -= msgsize_total
        conn.ibuf = msg_buffer[idx:]
    def process_conn_input(self, connection, conn_obj):
        if connection is self.server_socket:
            self.process_server_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is None:
            self.process_peer_init_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'P':
            self.process_peer_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'F':
            self.process_file_input(conn_obj, conn_obj.ibuf)
        elif conn_obj.init is not None and conn_obj.init.conn_type == 'D':
            self.process_distrib_input(conn_obj, conn_obj.ibuf)
        else:
            log.add("Can't handle connection type %s", conn_obj.init.conn_type)
    def run(self):
        self.selector.register(self.listen_socket, selectors.EVENT_READ)
        while not self._want_abort:
            if self.server_disconnected:
                time.sleep(0.1)
                continue
            curtime = time.time()
            if (curtime - self.last_conncount_callback) > self.CONNCOUNT_CALLBACK_INTERVAL:
                self._callback_msgs.append(SetCurrentConnectionCount(self._numsockets))
                self.last_conncount_callback = curtime
            if self._queue:
                self.process_conn_output()
            try:
                key_events = self.selector.select(timeout=-1)
                input_list = set(key.fileobj for key, event in key_events if event & selectors.EVENT_READ)
                output_list = set(key.fileobj for key, event in key_events if event & selectors.EVENT_WRITE)
            except OSError as error:
                log.add("Major Socket Error: Networking terminated! %s", error)
                self._want_abort = True
            except ValueError as error:
                log.add("select ValueError: %s", error)
                time.sleep(0.1)
                self._callback_msgs.clear()
                continue
            if self._numsockets < MAXSOCKETS and not self.server_disconnected and self.listen_socket in input_list:
                try:
                    incconn, incaddr = self.listen_socket.accept()
                except Exception:
                    time.sleep(0.01)
                else:
                    if self._network_filter.is_ip_blocked(incaddr[0]):
                        log.add_conn("Ignoring connection request from blocked IP address %(ip)s:%(port)s", {
                            'ip': incaddr[0],
                            'port': incaddr[1]
                        })
                        incconn.close()
                    else:
                        events = selectors.EVENT_READ
                        incconn.setblocking(0)
                        self._conns[incconn] = PeerConnection(conn=incconn, addr=incaddr, events=events)
                        self._numsockets += 1
                        self._callback_msgs.append(IncConn(incconn, incaddr))
                        self.selector.register(incconn, events)
            for connection_in_progress in self._connsinprogress.copy():
                try:
                    conn_obj = self._connsinprogress[connection_in_progress]
                except KeyError:
                    continue
                msg_obj = conn_obj.msg_obj
                if (curtime - conn_obj.lastactive) > self.IN_PROGRESS_STALE_AFTER:
                    self._callback_msgs.append(ConnectError(msg_obj, "Timed out"))
                    self.close_connection(self._connsinprogress, connection_in_progress)
                    continue
                try:
                    if connection_in_progress in input_list:
                        connection_in_progress.recv(1, socket.MSG_PEEK)
                except socket.error as err:
                    self._callback_msgs.append(ConnectError(msg_obj, err))
                    self.close_connection(self._connsinprogress, connection_in_progress)
                else:
                    if connection_in_progress in output_list:
                        addr = msg_obj.addr
                        events = selectors.EVENT_READ | selectors.EVENT_WRITE
                        if connection_in_progress is self.server_socket:
                            self._conns[self.server_socket] = Connection(
                                conn=self.server_socket, addr=addr, events=events)
                            self._callback_msgs.append(InitServerConn(self.server_socket, addr))
                        else:
                            if self._network_filter.is_ip_blocked(addr[0]):
                                log.add_conn("Ignoring connection request from blocked IP address %(ip)s:%(port)s", {
                                    "ip": addr[0],
                                    "port": addr[1]
                                })
                                self._callback_msgs.append(ConnectError(msg_obj, "Blocked IP address"))
                                self.close_connection(self._connsinprogress, connection_in_progress)
                                continue
                            self._conns[connection_in_progress] = PeerConnection(
                                conn=connection_in_progress, addr=addr, events=events, init=msg_obj.init)
                            self._callback_msgs.append(InitPeerConn(connection_in_progress, addr))
                        del self._connsinprogress[connection_in_progress]
            for connection in self._conns.copy():
                try:
                    conn_obj = self._conns[connection]
                except KeyError:
                    continue
                if (connection is not self.server_socket
                        and (curtime - conn_obj.lastactive) > self.CONNECTION_MAX_IDLE):
                    self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                    self.close_connection(self._conns, connection)
                    continue
                if connection in input_list:
                    if self._is_download(conn_obj):
                        self.set_conn_speed_limit(connection, self._download_limit_split, self._dlimits)
                    try:
                        if not self.read_data(conn_obj):
                            self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                            self.close_connection(self._conns, connection)
                            continue
                    except socket.error as err:
                        log.add_conn(("Cannot read data from connection %(addr)s, closing connection. "
                                      "Error: %(error)s"), {
                            "addr": conn_obj.addr,
                            "error": err
                        })
                        self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                        self.close_connection(self._conns, connection)
                        continue
                if conn_obj.ibuf:
                    self.process_conn_input(connection, conn_obj)
                if connection in output_list:
                    if self._is_upload(conn_obj):
                        self.set_conn_speed_limit(connection, self._upload_limit_split, self._ulimits)
                    try:
                        self.write_data(conn_obj)
                    except Exception as err:
                        log.add_conn("Cannot write data to connection %(addr)s, closing connection. Error: %(error)s", {
                            "addr": conn_obj.addr,
                            "error": err
                        })
                        self._callback_msgs.append(ConnClose(connection, conn_obj.addr))
                        self.close_connection(self._conns, connection)
                        continue
            if self._callback_msgs:
                self._core_callback(list(self._callback_msgs))
                self._callback_msgs.clear()
            self._ulimits = {}
            self._dlimits = {}
            self._calc_loops_per_second()
            time.sleep(1 / 60)
class NicotineCore:
    def send_message_to_peer(self, user, message, address=None):
        """ Sends message to a peer. Used primarily when we know the username of a peer,
        but don't have an active connection. """
        conn = None
        if message.__class__ is not slskmessages.FileRequest:
            """ Check if there's already a connection object for the specified username """
            for i in self.peerconns:
                if i.username == user and i.conn_type == 'P':
                    conn = i
                    log.add_conn("Found existing connection of type %(type)s for user %(user)s, using it.", {
                        'type': i.conn_type,
                        'user': user
                    })
                    break
        if conn is not None and conn.conn is not None:
            """ We have initiated a connection previously, and it's ready """
            conn.msgs.append(message)
            self.process_conn_messages(conn, conn.conn)
        elif conn is not None:
            """ Connection exists but is not ready yet, add new messages to it """
            conn.msgs.append(message)
        else:
            """ This is a new peer, initiate a connection """
            self.initiate_connection_to_peer(user, message, address)
        log.add_conn("Sending message of type %(type)s to user %(user)s", {
            'type': message.__class__,
            'user': user
        })
    def server_disconnect(self):
        if self.server_conn is None:
            return
        host, port = self.server_address
        log.add(
            _("Disconnected from server %(host)s:%(port)s"), {
                'host': host,
                'port': port
            })
        self.exit.set()
        if not self.manual_disconnect:
            self.set_server_timer()
        else:
            self.manual_disconnect = False
        self.server_conn = None
        self.server_address = None
        self.logged_in = False
        self.peerconns.clear()
        self.out_indirect_conn_request_times.clear()
        self.watched_users.clear()
        self.users.clear()
        self.pluginhandler.server_disconnect_notification(self.manual_disconnect)
        self.transfers.server_disconnect()
        self.search.server_disconnect()
        self.userlist.server_disconnect()
        self.chatrooms.server_disconnect()
        self.privatechats.server_disconnect()
        self.userinfo.server_disconnect()
        self.userbrowse.server_disconnect()
        if self.ui_callback:
            self.ui_callback.server_disconnect()
    def login(self, msg):
        """ Server code: 1 """
        log.add_msg_contents(msg)
        if msg.success:
            self.exit.clear()
            thread = threading.Thread(target=self._check_indirect_connection_timeouts)
            thread.name = "IndirectConnectionTimeoutTimer"
            thread.daemon = True
            thread.start()
            self.logged_in = True
            self.set_away_mode(config.sections["server"]["away"])
            self.watch_user(config.sections["server"]["login"])
            if msg.ip_address is not None:
                self.user_ip_address = msg.ip_address
            self.transfers.server_login()
            self.userbrowse.server_login()
            self.userinfo.server_login()
            self.userlist.server_login()
            self.privatechats.server_login()
            self.chatrooms.server_login()
            if self.ui_callback:
                self.ui_callback.server_login()
            if msg.banner:
                log.add(msg.banner)
            self.interests.server_login()
            self.queue.append(slskmessages.CheckPrivileges())
            self.send_have_no_parent()
            """ TODO: We can currently receive search requests from a parent connection, but
            redirecting results to children is not implemented yet. Tell the server we don't accept
            children for now. """
            self.queue.append(slskmessages.AcceptChildren(0))
            self.shares.send_num_shared_folders_files()
            """ Request a complete room list. A limited room list not including blacklisted rooms and
            rooms with few users is automatically sent when logging in, but subsequent room list
            requests contain all rooms. """
            self.queue.append(slskmessages.RoomList())
            self.queue.append(slskmessages.PrivateRoomToggle(config.sections["server"]["private_chatrooms"]))
            self.pluginhandler.server_connect_notification()
        else:
            self.manual_disconnect = True
            self.queue.append(slskmessages.ConnClose(self.server_conn))
            if msg.reason == "INVALIDPASS":
                self.ui_callback.invalid_password()
                return
            log.add_important_error(_("Unable to connect to the server. Reason: %s"), msg.reason)
class SlskMessage:
    def get_object(self, message, obj_type, start=0, getsignedint=False, getunsignedlonglong=False):
        """ Returns object of specified type, extracted from message (which is
        a binary array). start is an offset."""
        try:
            if obj_type is int:
                if getsignedint:
                    return INT_SIZE + start, INT_UNPACK(message[start:start + INT_SIZE])[0]
                if getunsignedlonglong:
                    try:
                        return INT64_SIZE + start, UINT64_UNPACK(message[start:start + INT64_SIZE])[0]
                    except Exception:
                        pass
                return INT_SIZE + start, UINT_UNPACK(message[start:start + INT_SIZE])[0]
            if obj_type is bytes:
                length = UINT_UNPACK(message[start:start + INT_SIZE])[0]
                content = message[start + INT_SIZE:start + length + INT_SIZE]
                return length + INT_SIZE + start, content
            if obj_type is str:
                length = UINT_UNPACK(message[start:start + INT_SIZE])[0]
                string = message[start + INT_SIZE:start + length + INT_SIZE]
                try:
                    string = str(string, "utf-8")
                except Exception:
                    try:
                        string = str(string, "latin-1")
                    except Exception as error:
                        log.add("Error trying to decode string '%s': %s", (string, error))
                return length + INT_SIZE + start, string
            return start, None
        except struct.error as error:
            log.add("%s %s trying to unpack %s at '%s' at %s/%s",
                    (self.__class__, error, obj_type, bytes(message[start:]), start, len(message)))
            raise struct.error(error)
