@implementer(IWriteLock, HTTPRangeSupport.HTTPRangeInterface)
class File(
    PathReprProvider,
    Persistent,
    Implicit,
    PropertyManager,
    RoleManager,
    Item_w__name__,
    Cacheable
):
    precondition = ''
    size = None
    def _if_modified_since_request_handler(self, REQUEST, RESPONSE):
        header = REQUEST.get_header('If-Modified-Since', None)
        if header is not None:
            header = header.split(';')[0]
            try:
                mod_since = int(DateTime(header).timeTime())
            except Exception:
                mod_since = None
            if mod_since is not None:
                if self._p_mtime:
                    last_mod = int(self._p_mtime)
                else:
                    last_mod = 0
                if last_mod > 0 and last_mod <= mod_since:
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setStatus(304)
                    return True
    def _range_request_handler(self, REQUEST, RESPONSE):
        range = REQUEST.get_header('Range', None)
        request_range = REQUEST.get_header('Request-Range', None)
        if request_range is not None:
            range = request_range
        if_range = REQUEST.get_header('If-Range', None)
        if range is not None:
            ranges = HTTPRangeSupport.parseRange(range)
            if if_range is not None:
                if len(if_range) > 1 and if_range[:2] == 'ts':
                    if if_range != self.http__etag():
                        ranges = None
                else:
                    date = if_range.split(';')[0]
                    try:
                        mod_since = int(DateTime(date).timeTime())
                    except Exception:
                        mod_since = None
                    if mod_since is not None:
                        if self._p_mtime:
                            last_mod = int(self._p_mtime)
                        else:
                            last_mod = 0
                        if last_mod > mod_since:
                            ranges = None
            if ranges:
                satisfiable = 0
                for start, end in ranges:
                    if start < self.size:
                        satisfiable = 1
                        break
                if not satisfiable:
                    RESPONSE.setHeader(
                        'Content-Range', 'bytes */%d' % self.size
                    )
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Content-Length', self.size)
                    RESPONSE.setStatus(416)
                    return True
                ranges = HTTPRangeSupport.expandRanges(ranges, self.size)
                if len(ranges) == 1:
                    start, end = ranges[0]
                    size = end - start
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Content-Length', size)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Content-Range',
                        'bytes %d-%d/%d' % (start, end - 1, self.size)
                    )
                    RESPONSE.setStatus(206)
                    data = self.data
                    if isinstance(data, bytes):
                        RESPONSE.write(data[start:end])
                        return True
                    pos = 0
                    while data is not None:
                        length = len(data.data)
                        pos = pos + length
                        if pos > start:
                            lstart = length - (pos - start)
                            if lstart < 0:
                                lstart = 0
                            if end <= pos:
                                lend = length - (pos - end)
                                RESPONSE.write(data[lstart:lend])
                                break
                            RESPONSE.write(data[lstart:])
                        data = data.next
                    return True
                else:
                    boundary = _make_boundary()
                    size = (8 + len(boundary)
                            + len(ranges) * (
                                49 + len(boundary)
                                + len(self.content_type)
                                + len('%d' % self.size)))
                    for start, end in ranges:
                        size = (size + len('%d%d' % (start, end - 1))
                                + end - start)
                    draftprefix = (request_range is not None) and 'x-' or ''
                    RESPONSE.setHeader('Content-Length', size)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader(
                        'Content-Type',
                        f'multipart/{draftprefix}byteranges;'
                        f' boundary={boundary}'
                    )
                    RESPONSE.setStatus(206)
                    data = self.data
                    pdata_map = {}
                    pdata_map[0] = data
                    for start, end in ranges:
                        RESPONSE.write(
                            b'\r\n--'
                            + boundary.encode('ascii')
                            + b'\r\n'
                        )
                        RESPONSE.write(
                            b'Content-Type: '
                            + self.content_type.encode('ascii')
                            + b'\r\n'
                        )
                        RESPONSE.write(
                            b'Content-Range: bytes '
                            + str(start).encode('ascii')
                            + b'-'
                            + str(end - 1).encode('ascii')
                            + b'/'
                            + str(self.size).encode('ascii')
                            + b'\r\n\r\n'
                        )
                        if isinstance(data, bytes):
                            RESPONSE.write(data[start:end])
                        else:
                            first_size = len(pdata_map[0].data)
                            if start < first_size:
                                closest_pos = 0
                            else:
                                closest_pos = (
                                    ((start - first_size) >> 16 << 16)
                                    + first_size
                                )
                            pos = min(closest_pos, max(pdata_map.keys()))
                            data = pdata_map[pos]
                            while data is not None:
                                length = len(data.data)
                                pos = pos + length
                                if pos > start:
                                    lstart = length - (pos - start)
                                    if lstart < 0:
                                        lstart = 0
                                    if end <= pos:
                                        lend = length - (pos - end)
                                        RESPONSE.write(data[lstart:lend])
                                        break
                                    RESPONSE.write(data[lstart:])
                                data = data.next
                                pdata_map[pos] = data
                    del pdata_map
                    RESPONSE.write(
                        b'\r\n--' + boundary.encode('ascii') + b'--\r\n')
                    return True
    @security.protected(View)
    def index_html(self, REQUEST, RESPONSE):
        """
        The default view of the contents of a File or Image.
        Returns the contents of the file or image.  Also, sets the
        Content-Type HTTP header to the objects content type.
        """
        if self._if_modified_since_request_handler(REQUEST, RESPONSE):
            self.ZCacheable_set(None)
            return b''
        if self.precondition and hasattr(self, str(self.precondition)):
            c = getattr(self, str(self.precondition))
            if hasattr(c, 'isDocTemp') and c.isDocTemp:
                c(REQUEST['PARENTS'][1], REQUEST)
            else:
                c()
        if self._range_request_handler(REQUEST, RESPONSE):
            return b''
        RESPONSE.setHeader('Last-Modified', rfc1123_date(self._p_mtime))
        RESPONSE.setHeader('Content-Type', self.content_type)
        RESPONSE.setHeader('Content-Length', self.size)
        RESPONSE.setHeader('Accept-Ranges', 'bytes')
        if self.ZCacheable_isCachingEnabled():
            result = self.ZCacheable_get(default=None)
            if result is not None:
                return result
        self.ZCacheable_set(None)
        data = self.data
        if isinstance(data, bytes):
            RESPONSE.setBase(None)
            return data
        while data is not None:
            RESPONSE.write(data.data)
            data = data.next
        return b''
    @security.protected(webdav_access)
    def manage_DAVget(self):
        """Return body for WebDAV."""
        RESPONSE = self.REQUEST.RESPONSE
        if self.ZCacheable_isCachingEnabled():
            result = self.ZCacheable_get(default=None)
            if result is not None:
                RESPONSE.setHeader('Content-Length', self.size)
                return result
        data = self.data
        if isinstance(data, bytes):
            RESPONSE.setBase(None)
            return data
        while data is not None:
            RESPONSE.write(data.data)
            data = data.next
        return b''

logger = logging.getLogger(__name__)
class MultiDomainBasicAuth(AuthBase):
    def _get_new_credentials(self, original_url, allow_netrc=True,
                             allow_keyring=True):
        """Find and return credentials for the specified URL."""
        url, netloc, url_user_password = split_auth_netloc_from_url(
            original_url)
        username, password = url_user_password
        if username is not None and password is not None:
            logger.debug("Found credentials in url for %s", netloc)
            return url_user_password
        index_url = self._get_index_url(url)
        if index_url:
            index_info = split_auth_netloc_from_url(index_url)
            if index_info:
                index_url, _, index_url_user_password = index_info
                logger.debug("Found index url %s", index_url)
        if index_url and index_url_user_password[0] is not None:
            username, password = index_url_user_password
            if username is not None and password is not None:
                logger.debug("Found credentials in index url for %s", netloc)
                return index_url_user_password
        if allow_netrc:
            netrc_auth = get_netrc_auth(original_url)
            if netrc_auth:
                logger.debug("Found credentials in netrc for %s", netloc)
                return netrc_auth
        if allow_keyring:
            kr_auth = (_get_keyring_auth(index_url, username) or
                       _get_keyring_auth(netloc, username))
            if kr_auth:
                logger.debug("Found credentials in keyring for %s", netloc)
                return kr_auth
        return None, None
class LocalFSAdapter(BaseAdapter):
    def send(self, request, stream=None, timeout=None, verify=None, cert=None,
             proxies=None):
        pathname = url_to_path(request.url)
        resp = Response()
        resp.status_code = 200
        resp.url = request.url
        try:
            stats = os.stat(pathname)
        except OSError as exc:
            resp.status_code = 404
            resp.raw = exc
        else:
            modified = email.utils.formatdate(stats.st_mtime, usegmt=True)
            content_type = mimetypes.guess_type(pathname)[0] or "text/plain"
            resp.headers = CaseInsensitiveDict({
                "Content-Type": content_type,
                "Content-Length": stats.st_size,
                "Last-Modified": modified,
            })
            resp.raw = open(pathname, "rb")
            resp.close = resp.raw.close
        return resp
