            default=None if allow_none else _PropBase.NO_DEFAULT,
            validator=xso_types.RestrictToSet(values),
            validate=ValidateMode.ALWAYS)
        self.child_map = tags
        self.text_policy = text_policy
        self.attr_policy = attr_policy
