                collected_text = "".join(collected_text)
                try:
                    cls.TEXT_PROPERTY.xq_descriptor.from_value(
                        obj,
                        collected_text
                    )
                except:
                    logger.debug("while parsing XSO", exc_info=True)
                    if not obj.xso_error_handler(
                            cls.TEXT_PROPERTY.xq_descriptor,
                            collected_text,
                            sys.exc_info()):
                        raise
