            if not template_base_path.exists():
                if not (app_directory / "templates").exists():
                    (app_directory / "templates").mkdir()
                template_base_path.mkdir()
            template_path = template_base_path / f"{component_name}.html"
            if template_path.exists():
                self.stdout.write(
                    self.style.ERROR(
